ALTER TABLE ONLY public.nrd_schedules ADD CONSTRAINT nrd_schedules_when_check CHECK ((((repeat = 'once'::text) AND (schedule_date IS NOT NULL) AND (weekday IS NULL)) OR ((repeat = 'weekly'::text) AND (weekday IS NOT NULL) AND (schedule_date IS NULL))));

