ALTER TABLE ONLY public.packaging_rules ADD CONSTRAINT packaging_rules_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.packaging_rules ADD CONSTRAINT packaging_rules_max_trigger_count_check CHECK (((max_trigger_count IS NULL) OR ((max_trigger_count >= 1) AND (max_trigger_count <= 100000))));

ALTER TABLE ONLY public.packaging_rules ADD CONSTRAINT packaging_rules_not_itself CHECK ((trigger_packaging_type_id IS DISTINCT FROM packaging_type_id));

ALTER TABLE ONLY public.packaging_rules ADD CONSTRAINT packaging_rules_quantity_check CHECK (((quantity >= 1) AND (quantity <= 1000)));

ALTER TABLE ONLY public.packaging_rules ADD CONSTRAINT packaging_rules_single_trigger CHECK ((num_nonnulls(trigger_packaging_type_id, trigger_device_id) = 1));

