ALTER TABLE ONLY public.packaging_stock_movements ADD CONSTRAINT packaging_movement_reserved_valid CHECK ((reserved_after <= on_hand_after));

ALTER TABLE ONLY public.packaging_stock_movements ADD CONSTRAINT packaging_stock_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['RECEIVE'::text, 'REMOVE'::text, 'COUNT_ADJUSTMENT'::text, 'RESERVE'::text, 'RELEASE'::text, 'CONSUME'::text, 'UNDO_CONSUME'::text])));

