ALTER TABLE ONLY public.packaging_stock_movements ADD CONSTRAINT packaging_stock_movements_reason_check CHECK (((char_length(btrim(reason)) >= 1) AND (char_length(btrim(reason)) <= 500)));

ALTER TABLE ONLY public.packaging_stock_movements ADD CONSTRAINT packaging_stock_movements_reserved_after_check CHECK ((reserved_after >= 0));

ALTER TABLE ONLY public.packaging_stock_movements ADD CONSTRAINT packaging_stock_movements_reserved_before_check CHECK ((reserved_before >= 0));

