ALTER TABLE ONLY public.packaging_types ADD CONSTRAINT packaging_types_dimensions_check CHECK ((((category = 'SLEEVE'::text) AND (length_cm IS NULL) AND (width_cm IS NULL) AND (height_cm IS NULL)) OR ((category <> 'SLEEVE'::text) AND (length_cm IS NOT NULL) AND (length_cm > (0)::numeric) AND (length_cm <= (1000)::numeric) AND (width_cm IS NOT NULL) AND (width_cm > (0)::numeric) AND (width_cm <= (1000)::numeric) AND (height_cm IS NOT NULL) AND (height_cm > (0)::numeric) AND (height_cm <= (1000)::numeric))));

