CREATE OR REPLACE FUNCTION private.has_active_app_session(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select exists (
    select 1
    from public.profiles p
    where p.user_id = uid
      and p.current_session_id = (select auth.jwt() ->> 'session_id')
      and p.last_seen_at >= statement_timestamp() - interval '1 hour'
  );
$function$;

CREATE OR REPLACE FUNCTION private.has_app_role(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select private.has_active_app_session(uid) and exists (
    select 1
    from public.user_roles r
    where r.user_id = uid
      and r.role in ('admin', 'operator', 'viewer')
  );
$function$;

CREATE OR REPLACE FUNCTION private.has_permission(uid uuid, permission_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select private.has_active_app_session(uid) and (
    private.is_admin(uid) or exists (
      select 1
      from public.user_permissions p
      where p.user_id = uid
        and case permission_name
          when 'can_dashboard' then p.can_dashboard
          when 'can_inventory_export' then p.can_inventory_export
          when 'can_inbound' then p.can_inbound
          when 'can_outbound' then p.can_outbound
          when 'can_returns' then p.can_returns
          when 'can_transfer' then p.can_transfer
          when 'can_labels' then p.can_labels
          when 'can_bins' then p.can_bins
          when 'can_accessories' then p.can_accessories
          when 'can_supply' then p.can_supply
          when 'can_nrd' then p.can_nrd
          when 'can_admin' then false
          else false
        end
    )
  );
$function$;

CREATE OR REPLACE FUNCTION private.is_admin(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select private.has_active_app_session(uid) and exists (
    select 1
    from public.user_roles r
    where r.user_id = uid
      and r.role = 'admin'
  );
$function$;

CREATE OR REPLACE FUNCTION public.acquire_workload_lease(p_route_class text, p_principal_hash text, p_source_hash text, p_window_seconds integer, p_principal_limit integer, p_source_limit integer, p_global_limit integer, p_principal_concurrency integer, p_route_concurrency integer, p_global_concurrency integer, p_lease_seconds integer)
 RETURNS TABLE(allowed boolean, lease_id uuid, retry_after_seconds integer, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_window timestamptz;
  v_principal_used integer;
  v_source_used integer;
  v_global_used integer;
  v_principal_active integer;
  v_route_active integer;
  v_global_active integer;
  v_lease_id uuid;
  v_retry integer;
begin
  if nullif(btrim(p_route_class), '') is null
    or char_length(p_route_class) > 100
    or p_principal_hash !~ '^[0-9a-f]{64}$'
    or p_source_hash !~ '^[0-9a-f]{64}$'
    or p_window_seconds not between 1 and 3600
    or p_principal_limit not between 1 and 100000
    or p_source_limit not between 1 and 100000
    or p_global_limit not between 1 and 1000000
    or p_principal_concurrency not between 1 and 1000
    or p_route_concurrency not between 1 and 1000
    or p_global_concurrency not between 1 and 10000
    or p_principal_concurrency > p_route_concurrency
    or p_route_concurrency > p_global_concurrency
    or p_lease_seconds not between 1 and 900 then
    raise exception 'WORKLOAD_POLICY_INVALID' using errcode = '22023';
  end if;

  v_window := to_timestamp(
    floor(extract(epoch from v_now) / p_window_seconds) * p_window_seconds
  );
  v_retry := greatest(
    1,
    ceil(
      extract(
        epoch from (
          v_window
          + p_window_seconds * interval '1 second'
          - v_now
        )
      )
    )::integer
  );

  -- A consistent lock order makes the rate and concurrency decision atomic
  -- across routes and serverless instances.
  perform pg_advisory_xact_lock(
    hashtextextended('stockpro-workload:global', 0)
  );
  perform pg_advisory_xact_lock(
    hashtextextended('stockpro-workload:' || p_route_class, 0)
  );

  select coalesce(max(b.used), 0)
  into v_principal_used
  from public.workload_budget_buckets b
  where b.route_class = p_route_class
    and b.scope = 'principal'
    and b.scope_key_hash = p_principal_hash
    and b.window_started_at = v_window;

  select coalesce(max(b.used), 0)
  into v_source_used
  from public.workload_budget_buckets b
  where b.route_class = p_route_class
    and b.scope = 'source'
    and b.scope_key_hash = p_source_hash
    and b.window_started_at = v_window;

  select coalesce(max(b.used), 0)
  into v_global_used
  from public.workload_budget_buckets b
  where b.route_class = p_route_class
    and b.scope = 'global'
    and b.scope_key_hash = 'global'
    and b.window_started_at = v_window;

  if v_principal_used >= p_principal_limit
    or v_source_used >= p_source_limit
    or v_global_used >= p_global_limit then
    return query
      select false, null::uuid, v_retry, 'rate_limited'::text;
    return;
  end if;

  select count(*)::integer
  into v_global_active
  from public.workload_leases l
  where l.expires_at > v_now;

  select count(*)::integer
  into v_route_active
  from public.workload_leases l
  where l.route_class = p_route_class
    and l.expires_at > v_now;

  select count(*)::integer
  into v_principal_active
  from public.workload_leases l
  where l.route_class = p_route_class
    and l.principal_hash = p_principal_hash
    and l.expires_at > v_now;

  if v_principal_active >= p_principal_concurrency
    or v_route_active >= p_route_concurrency
    or v_global_active >= p_global_concurrency then
    return query
      select false, null::uuid, 2, 'concurrency_limited'::text;
    return;
  end if;

  insert into public.workload_budget_buckets (
    route_class,
    scope,
    scope_key_hash,
    window_started_at,
    used
  )
  values
    (p_route_class, 'global', 'global', v_window, 1),
    (p_route_class, 'principal', p_principal_hash, v_window, 1),
    (p_route_class, 'source', p_source_hash, v_window, 1)
  on conflict (route_class, scope, scope_key_hash, window_started_at)
  do update set used = public.workload_budget_buckets.used + 1;

  insert into public.workload_leases (
    route_class,
    principal_hash,
    source_hash,
    acquired_at,
    expires_at
  )
  values (
    p_route_class,
    p_principal_hash,
    p_source_hash,
    v_now,
    v_now + p_lease_seconds * interval '1 second'
  )
  returning id into v_lease_id;

  return query select true, v_lease_id, 0, 'admitted'::text;
end;
$function$;

CREATE OR REPLACE FUNCTION public.activate_app_session(p_user_id uuid, p_session_id text, p_email text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_current_session_id text;
  v_last_seen_at timestamptz;
begin
  if p_session_id is null
     or p_session_id !~ '^[A-Za-z0-9_-]{1,128}$' then
    raise exception 'invalid application session'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('stockpro-app-session:' || p_user_id::text, 0)
  );

  select current_session_id, last_seen_at
    into v_current_session_id, v_last_seen_at
  from public.profiles
  where user_id = p_user_id
  for update;

  if not found then
    insert into public.profiles (
      user_id,
      email,
      current_session_id,
      last_seen_at
    ) values (
      p_user_id,
      lower(p_email),
      p_session_id,
      statement_timestamp()
    );
    return 'activated';
  end if;

  if v_current_session_id is not null
     and v_current_session_id <> p_session_id
     and v_last_seen_at >= statement_timestamp() - interval '2 minutes' then
    return 'conflict';
  end if;

  update public.profiles
  set current_session_id = p_session_id,
      last_seen_at = statement_timestamp()
  where user_id = p_user_id;

  return 'activated';
end;
$function$;

CREATE OR REPLACE FUNCTION public.adjust_packaging_stock(p_operation_id uuid, p_actor_id uuid, p_actor text, p_packaging_type_id uuid, p_mode text, p_quantity integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_packaging public.packaging_types%rowtype;
  v_delta integer;
  v_after integer;
  v_movement_type text;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'PACKAGING_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if p_packaging_type_id is null
    or lower(coalesce(p_mode, '')) not in ('receive', 'remove', 'set')
    or p_quantity is null
    or p_quantity < 0
    or p_quantity > 10000000
    or nullif(btrim(coalesce(p_reason, '')), '') is null
    or char_length(btrim(p_reason)) > 500 then
    raise exception 'PACKAGING_ADJUSTMENT_INVALID' using errcode = '22023';
  end if;

  if lower(p_mode) in ('receive', 'remove') and p_quantity = 0 then
    raise exception 'PACKAGING_ADJUSTMENT_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'packaging_adjustment',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'packaging_adjustment'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select packaging.*
  into v_packaging
  from public.packaging_types packaging
  where packaging.id = p_packaging_type_id
  for update of packaging;

  if not found then
    raise exception 'PACKAGING_NOT_FOUND' using errcode = 'P0002';
  end if;

  if not v_packaging.active then
    raise exception 'PACKAGING_INACTIVE' using errcode = '23514';
  end if;

  if lower(p_mode) = 'receive' then
    v_delta := p_quantity;
    v_movement_type := 'RECEIVE';
  elsif lower(p_mode) = 'remove' then
    v_delta := -p_quantity;
    v_movement_type := 'REMOVE';
  else
    v_delta := p_quantity - v_packaging.on_hand_stock;
    v_movement_type := 'COUNT_ADJUSTMENT';
  end if;

  if v_delta = 0 then
    raise exception 'PACKAGING_NO_STOCK_CHANGE' using errcode = '22023';
  end if;

  v_after := v_packaging.on_hand_stock + v_delta;
  if v_after < v_packaging.reserved_stock then
    raise exception 'PACKAGING_STOCK_BELOW_RESERVED:%:%:%',
      v_packaging.name,
      v_after,
      v_packaging.reserved_stock
      using errcode = '23514';
  end if;

  update public.packaging_types packaging
  set on_hand_stock = v_after,
      updated_at = v_now,
      updated_by_id = p_actor_id,
      updated_by_email = btrim(p_actor)
  where packaging.id = v_packaging.id;

  insert into public.packaging_stock_movements (
    operation_id,
    packaging_type_id,
    movement_type,
    on_hand_delta,
    reserved_delta,
    on_hand_before,
    on_hand_after,
    reserved_before,
    reserved_after,
    reason,
    actor_id,
    actor_email,
    created_at
  )
  values (
    p_operation_id,
    v_packaging.id,
    v_movement_type,
    v_delta,
    0,
    v_packaging.on_hand_stock,
    v_after,
    v_packaging.reserved_stock,
    v_packaging.reserved_stock,
    btrim(p_reason),
    p_actor_id,
    btrim(p_actor),
    v_now
  );

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'row', jsonb_build_object(
      'id', v_packaging.id,
      'code', v_packaging.code,
      'name', v_packaging.name,
      'on_hand_stock', v_after,
      'reserved_stock', v_packaging.reserved_stock,
      'available_stock', v_after - v_packaging.reserved_stock,
      'minimum_stock', v_packaging.minimum_stock
    )
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_existing_imeis(requested_imeis text[])
 RETURNS TABLE(imei text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if (select auth.uid()) is null
     or not private.has_permission((select auth.uid()), 'can_inbound') then
    raise exception 'insufficient privilege'
      using errcode = '42501';
  end if;

  if requested_imeis is null
     or cardinality(requested_imeis) not between 1 and 200 then
    raise exception 'requested_imeis must contain between 1 and 200 values'
      using errcode = '22023';
  end if;

  return query
    select distinct i.imei::text
    from public.items i
    where i.imei = any(requested_imeis);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_stock_before_out()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    current_stock integer;
BEGIN
    IF NEW.type = 'OUT' THEN

        SELECT COUNT(*)
        INTO current_stock
        FROM items
        WHERE device_id = NEW.device_id
        AND status = 'IN';

        IF current_stock <= 0 THEN
            RAISE EXCEPTION 'No stock available for device %', NEW.device_id;
        END IF;

    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.claim_return_template_export_batch(p_batch_id uuid, p_actor_id uuid, p_actor text, p_limit integer DEFAULT 50000)
 RETURNS TABLE(id uuid, operation_id uuid, created_at timestamp with time zone, return_status text, imei text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_claimed integer;
  v_now timestamptz := clock_timestamp();
begin
  if p_batch_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'RETURN_TEMPLATE_EXPORT_IDENTITY_REQUIRED'
      using errcode = '22023';
  end if;

  if p_limit is null or p_limit not between 1 and 50000 then
    raise exception 'RETURN_TEMPLATE_EXPORT_LIMIT_INVALID'
      using errcode = '22023';
  end if;

  insert into public.return_template_export_batches (
    id,
    created_at,
    actor_id,
    actor,
    row_count
  )
  values (
    p_batch_id,
    v_now,
    p_actor_id,
    btrim(p_actor),
    0
  );

  return query
  with pending as (
    select r.id
    from public.return_records r
    where r.template_exported_at is null
    order by r.created_at, r.id
    for update of r skip locked
    limit p_limit
  ), claimed as (
    update public.return_records r
    set template_export_batch_id = p_batch_id,
        template_exported_at = v_now,
        template_exported_by = p_actor_id,
        template_exported_by_email = btrim(p_actor)
    from pending
    where r.id = pending.id
    returning r.id, r.operation_id, r.created_at, r.return_status, r.imei
  )
  select c.id, c.operation_id, c.created_at, c.return_status, c.imei
  from claimed c
  order by c.created_at, c.id;

  get diagnostics v_claimed = row_count;

  if v_claimed = 0 then
    delete from public.return_template_export_batches
    where return_template_export_batches.id = p_batch_id;
  else
    update public.return_template_export_batches
    set row_count = v_claimed
    where return_template_export_batches.id = p_batch_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_return_template_export_batch_v2(p_batch_id uuid, p_actor_id uuid, p_actor text, p_limit integer DEFAULT 50000)
 RETURNS TABLE(id uuid, operation_id uuid, created_at timestamp with time zone, return_status text, return_reason text, imei text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    claimed.id,
    claimed.operation_id,
    claimed.created_at,
    claimed.return_status,
    records.return_reason,
    claimed.imei
  from public.claim_return_template_export_batch(
    p_batch_id,
    p_actor_id,
    p_actor,
    p_limit
  ) claimed
  join public.return_records records on records.id = claimed.id
  order by claimed.created_at, claimed.id;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_accessory_outbound(p_operation_id uuid, p_actor_id uuid, p_actor text, p_source text, p_shipment_ref text, p_note text, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_bad_name text;
  v_bad_stock integer;
  v_bad_qty integer;
  v_bin record;
  v_after_stock integer;
  v_removed jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'ACCESSORY_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if p_source not in ('manual', 'excel')
    or char_length(coalesce(p_shipment_ref, '')) > 500
    or char_length(coalesce(p_note, '')) > 1000 then
    raise exception 'ACCESSORY_METADATA_INVALID' using errcode = '22023';
  end if;

  if jsonb_typeof(p_lines) is distinct from 'array'
    or jsonb_array_length(p_lines) not between 1 and 500 then
    raise exception 'ACCESSORY_LINE_LIMIT' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_lines) as entry(line)
    where jsonb_typeof(entry.line) is distinct from 'object'
      or coalesce(entry.line->>'accessory_bin_id', '') !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      or coalesce(entry.line->>'qty', '') !~ '^[1-9][0-9]{0,6}$'
  ) then
    raise exception 'ACCESSORY_LINE_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'accessory_outbound',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'accessory_outbound'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  with requested as (
    select (entry.line->>'accessory_bin_id')::uuid as accessory_bin_id,
           sum((entry.line->>'qty')::integer)::integer as qty
    from jsonb_array_elements(p_lines) as entry(line)
    group by (entry.line->>'accessory_bin_id')::uuid
  )
  select count(*)
  into v_requested_count
  from requested;

  perform bin.id
  from public.accessory_bins bin
  join (
    select (entry.line->>'accessory_bin_id')::uuid as accessory_bin_id
    from jsonb_array_elements(p_lines) as entry(line)
    group by (entry.line->>'accessory_bin_id')::uuid
  ) requested on requested.accessory_bin_id = bin.id
  order by bin.id
  for update of bin;

  with requested as (
    select (entry.line->>'accessory_bin_id')::uuid as accessory_bin_id
    from jsonb_array_elements(p_lines) as entry(line)
    group by (entry.line->>'accessory_bin_id')::uuid
  )
  select count(*)
  into v_found_count
  from requested
  join public.accessory_bins bin on bin.id = requested.accessory_bin_id
  where bin.active;

  if v_found_count <> v_requested_count then
    raise exception 'ACCESSORY_BINS_NOT_FOUND' using errcode = 'P0002';
  end if;

  with requested as (
    select (entry.line->>'accessory_bin_id')::uuid as accessory_bin_id,
           sum((entry.line->>'qty')::integer)::integer as qty
    from jsonb_array_elements(p_lines) as entry(line)
    group by (entry.line->>'accessory_bin_id')::uuid
  )
  select bin.name, bin.current_stock, requested.qty
  into v_bad_name, v_bad_stock, v_bad_qty
  from requested
  join public.accessory_bins bin on bin.id = requested.accessory_bin_id
  where bin.current_stock < requested.qty
  order by bin.id
  limit 1;

  if v_bad_name is not null then
    raise exception 'ACCESSORY_STOCK_INSUFFICIENT:%:%:%',
      v_bad_name, v_bad_stock, v_bad_qty
      using errcode = '23514';
  end if;

  for v_bin in
    with requested as (
      select (entry.line->>'accessory_bin_id')::uuid as accessory_bin_id,
             sum((entry.line->>'qty')::integer)::integer as qty
      from jsonb_array_elements(p_lines) as entry(line)
      group by (entry.line->>'accessory_bin_id')::uuid
    )
    select bin.id, bin.name, bin.current_stock, requested.qty
    from requested
    join public.accessory_bins bin on bin.id = requested.accessory_bin_id
    order by bin.id
  loop
    update public.accessory_bins as bin
    set current_stock = bin.current_stock - v_bin.qty
    where bin.id = v_bin.id
      and bin.current_stock >= v_bin.qty
    returning current_stock into v_after_stock;

    if not found then
      raise exception 'ACCESSORY_STOCK_CHANGED' using errcode = '40001';
    end if;

    insert into public.accessory_movements (
      accessory_bin_id,
      qty,
      movement_type,
      shipment_ref,
      note,
      actor,
      actor_id,
      source,
      operation_id
    )
    values (
      v_bin.id,
      v_bin.qty,
      'OUT',
      nullif(btrim(coalesce(p_shipment_ref, '')), ''),
      nullif(btrim(coalesce(p_note, '')), ''),
      btrim(p_actor),
      p_actor_id,
      p_source,
      p_operation_id
    );

    v_removed := v_removed || jsonb_build_array(
      jsonb_build_object(
        'accessory_bin_id', v_bin.id,
        'accessory', v_bin.name,
        'qty', v_bin.qty,
        'current_stock', v_bin.current_stock,
        'after_stock', v_after_stock
      )
    );
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'removed', v_removed,
    'rows', v_removed
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_dispatch_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_source_sha256 text, p_source_filename text, p_source_generated_at text, p_orders jsonb, p_package_usage jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_order_ids text[];
  v_order_count integer;
  v_line_count integer;
  v_total_packages integer;
  v_batch_id uuid;
  v_usage jsonb;
  v_packaging public.packaging_types%rowtype;
  v_packaging_id uuid;
  v_quantity integer;
  v_after integer;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'DISPATCH_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if coalesce(p_source_sha256, '') !~ '^[a-f0-9]{64}$'
    or nullif(btrim(coalesce(p_source_filename, '')), '') is null
    or char_length(btrim(p_source_filename)) > 255
    or jsonb_typeof(p_orders) is distinct from 'array'
    or jsonb_typeof(p_package_usage) is distinct from 'array' then
    raise exception 'DISPATCH_PAYLOAD_INVALID' using errcode = '22023';
  end if;

  v_order_count := jsonb_array_length(p_orders);
  select coalesce(array_agg(order_id order by order_id), '{}'),
         coalesce(sum(line_count), 0)
  into v_order_ids, v_line_count
  from (
    select nullif(btrim(value ->> 'orderId'), '') as order_id,
           coalesce((value ->> 'lineCount')::integer, 0) as line_count
    from jsonb_array_elements(p_orders)
  ) parsed;

  select coalesce(sum((value ->> 'quantity')::integer), 0)
  into v_total_packages
  from jsonb_array_elements(p_package_usage);

  if v_order_count not between 1 and 5000
    or cardinality(v_order_ids) <> v_order_count
    or exists (select 1 from unnest(v_order_ids) value where value is null)
    or cardinality(array(select distinct value from unnest(v_order_ids) value)) <> v_order_count
    or v_line_count not between 1 and 50000
    or jsonb_array_length(p_package_usage) not between 1 and 100
    or v_total_packages not between 1 and 1000000 then
    raise exception 'DISPATCH_PAYLOAD_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  ) values (
    p_operation_id,
    'dispatch_confirm',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;
  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'dispatch_confirm'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;
    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;
    return v_existing_result;
  end if;

  perform pg_advisory_xact_lock(hashtext('stockpro-dispatch-planning'));

  if exists (
    select 1
    from public.dispatch_batches batch
    where batch.status = 'CONFIRMED'
      and batch.source_sha256 = p_source_sha256
  ) then
    raise exception 'DISPATCH_SOURCE_ALREADY_CONFIRMED' using errcode = '23505';
  end if;

  if exists (
    select 1
    from public.dispatch_batches batch
    where batch.status = 'CONFIRMED'
      and batch.order_ids && v_order_ids
  ) then
    raise exception 'DISPATCH_ORDERS_ALREADY_CONFIRMED' using errcode = '23505';
  end if;

  for v_usage in select value from jsonb_array_elements(p_package_usage)
  loop
    if coalesce(v_usage ->> 'packagingTypeId', '') !~
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(v_usage ->> 'quantity', '') !~ '^[1-9][0-9]{0,6}$' then
      raise exception 'DISPATCH_PACKAGING_INVALID' using errcode = '22023';
    end if;

    v_packaging_id := (v_usage ->> 'packagingTypeId')::uuid;
    v_quantity := (v_usage ->> 'quantity')::integer;

    select packaging.*
    into v_packaging
    from public.packaging_types packaging
    where packaging.id = v_packaging_id
    for update of packaging;

    if not found then
      raise exception 'PACKAGING_NOT_FOUND' using errcode = 'P0002';
    end if;
    if not v_packaging.active then
      raise exception 'PACKAGING_INACTIVE' using errcode = '23514';
    end if;
    if v_packaging.on_hand_stock - v_packaging.reserved_stock < v_quantity then
      raise exception 'DISPATCH_PACKAGING_INSUFFICIENT:%:%:%',
        v_packaging.name,
        v_packaging.on_hand_stock - v_packaging.reserved_stock,
        v_quantity
        using errcode = '23514';
    end if;

    v_after := v_packaging.on_hand_stock - v_quantity;
    update public.packaging_types packaging
    set on_hand_stock = v_after,
        updated_at = v_now,
        updated_by_id = p_actor_id,
        updated_by_email = btrim(p_actor)
    where packaging.id = v_packaging.id;

    insert into public.packaging_stock_movements (
      operation_id,
      packaging_type_id,
      movement_type,
      on_hand_delta,
      reserved_delta,
      on_hand_before,
      on_hand_after,
      reserved_before,
      reserved_after,
      reason,
      actor_id,
      actor_email,
      created_at
    ) values (
      gen_random_uuid(),
      v_packaging.id,
      'CONSUME',
      -v_quantity,
      0,
      v_packaging.on_hand_stock,
      v_after,
      v_packaging.reserved_stock,
      v_packaging.reserved_stock,
      'Daily dispatch ' || btrim(p_source_filename),
      p_actor_id,
      btrim(p_actor),
      v_now
    );
  end loop;

  insert into public.dispatch_batches (
    operation_id,
    source_sha256,
    source_filename,
    source_generated_at,
    order_ids,
    orders,
    package_usage,
    order_count,
    line_count,
    total_packages,
    actor_id,
    actor_email,
    confirmed_at,
    created_at
  ) values (
    p_operation_id,
    p_source_sha256,
    btrim(p_source_filename),
    nullif(btrim(coalesce(p_source_generated_at, '')), ''),
    v_order_ids,
    p_orders,
    p_package_usage,
    v_order_count,
    v_line_count,
    v_total_packages,
    p_actor_id,
    btrim(p_actor),
    v_now,
    v_now
  ) returning id into v_batch_id;

  v_result := jsonb_build_object(
    'ok', true,
    'batch_id', v_batch_id,
    'operation_id', p_operation_id,
    'order_count', v_order_count,
    'line_count', v_line_count,
    'total_packages', v_total_packages,
    'status', 'CONFIRMED'
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_inbound_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_vendor text, p_source text, p_shipment_ref text, p_labels jsonb, p_skip_included_accessories uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_missing_bins text;
  v_imei text;
  v_raw_imei_count integer;
  v_all_imeis integer;
  v_existing_imeis integer;
  v_new_imeis integer;
  v_batch_id uuid;
  v_batch_created_at timestamp;
  v_desired_boxes integer;
  v_created_boxes integer;
  v_reused_boxes integer;
  v_inserted_imeis integer;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
  v_included record;
  v_accessory_stock integer;
  v_included_accessories jsonb := '[]'::jsonb;
begin
  if p_operation_id is null or p_actor_id is null or nullif(btrim(p_actor), '') is null then
    raise exception 'INBOUND_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if p_source is null or p_source not in ('excel', 'manual') then
    raise exception 'INBOUND_SOURCE_INVALID' using errcode = '22023';
  end if;

  if jsonb_typeof(p_labels) is distinct from 'array' then
    raise exception 'INBOUND_LABEL_LIMIT' using errcode = '22023';
  end if;

  if jsonb_array_length(p_labels) not between 1 and 1000 then
    raise exception 'INBOUND_LABEL_LIMIT' using errcode = '22023';
  end if;

  if char_length(coalesce(p_vendor, '')) > 200
    or char_length(coalesce(p_shipment_ref, '')) > 500 then
    raise exception 'INBOUND_METADATA_INVALID' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_labels) as entry(label)
    where jsonb_typeof(entry.label) is distinct from 'object'
      or coalesce(entry.label->>'device_id', '') !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      or nullif(btrim(entry.label->>'box_no'), '') is null
      or char_length(btrim(entry.label->>'box_no')) > 200
      or char_length(coalesce(entry.label->>'floor', '')) > 50
      or jsonb_typeof(entry.label->'imeis') is distinct from 'array'
      or case
        when jsonb_typeof(entry.label->'imeis') = 'array'
        then jsonb_array_length(entry.label->'imeis') = 0
        else true
      end
  ) then
    raise exception 'INBOUND_LABEL_INVALID' using errcode = '22023';
  end if;

  select sum(jsonb_array_length(entry.label->'imeis'))
  into v_raw_imei_count
  from jsonb_array_elements(p_labels) as entry(label);

  if coalesce(v_raw_imei_count, 0) not between 1 and 50000 then
    raise exception 'INBOUND_IMEI_LIMIT' using errcode = '22023';
  end if;

  -- 15-digit IMEIs, except the MatrixIQ bin: 12-digit serial numbers.
  if exists (
    select 1
    from jsonb_array_elements(p_labels) as entry(label)
    cross join lateral jsonb_array_elements(entry.label->'imeis') as raw_imei(value)
    left join public.bins bin
      on bin.id::text = lower(entry.label->>'device_id')
    where jsonb_typeof(raw_imei.value) is distinct from 'string'
      or (raw_imei.value #>> '{}') !~ public.stockpro_device_id_pattern(bin.name)
  ) then
    raise exception 'INBOUND_IMEI_INVALID' using errcode = '22023';
  end if;

  with requested_bins as (
    select distinct (entry.label->>'device_id')::uuid as bin_id
    from jsonb_array_elements(p_labels) as entry(label)
  )
  select string_agg(requested.bin_id::text, ', ' order by requested.bin_id::text)
  into v_missing_bins
  from requested_bins requested
  left join public.bins b on b.id = requested.bin_id
  where b.id is null;

  if v_missing_bins is not null then
    raise exception 'INBOUND_BINS_NOT_FOUND:%', v_missing_bins
      using errcode = 'P0002';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'inbound',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select r.command_type, r.actor_id, r.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts r
    where r.operation_id = p_operation_id;

    if v_existing_command is distinct from 'inbound'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  for v_imei in
    select distinct raw_imei.value #>> '{}'
    from jsonb_array_elements(p_labels) as entry(label)
    cross join lateral jsonb_array_elements(entry.label->'imeis') as raw_imei(value)
    order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_imei, 824651));
  end loop;

  with requested_imeis as (
    select distinct raw_imei.value #>> '{}' as imei
    from jsonb_array_elements(p_labels) as entry(label)
    cross join lateral jsonb_array_elements(entry.label->'imeis') as raw_imei(value)
  )
  select count(*),
         count(i.imei)
  into v_all_imeis, v_existing_imeis
  from requested_imeis requested
  left join public.items i on i.imei = requested.imei;

  v_new_imeis := v_all_imeis - v_existing_imeis;

  if v_new_imeis = 0 then
    v_result := jsonb_build_object(
      'ok', false,
      'code', 'ALL_IMEIS_ALREADY_IN_STOCK',
      'error',
        format(
          'Import blocked: all %s %s from this spreadsheet %s already in stock. Nothing was imported and no history was created.',
          v_all_imeis,
          case when v_all_imeis = 1 then 'IMEI' else 'IMEIs' end,
          case when v_all_imeis = 1 then 'is' else 'are' end
        ),
      'totals', jsonb_build_object(
        'inserted_imeis', 0,
        'skipped_existing_imeis', v_existing_imeis,
        'created_boxes', 0,
        'reused_boxes', 0
      )
    );

    update public.inventory_command_receipts
    set result = v_result
    where operation_id = p_operation_id;

    return v_result;
  end if;

  insert into public.inbound_batches (
    actor,
    vendor,
    source,
    shipment_ref
  )
  values (
    btrim(p_actor),
    coalesce(nullif(btrim(p_vendor), ''), 'unknown'),
    p_source,
    nullif(btrim(coalesce(p_shipment_ref, '')), '')
  )
  returning batch_id, created_at
  into v_batch_id, v_batch_created_at;

  with raw_labels as (
    select entry.ordinality as label_order,
           entry.label
    from jsonb_array_elements(p_labels)
      with ordinality as entry(label, ordinality)
  ),
  parsed_labels as (
    select raw.label_order,
           (raw.label->>'device_id')::uuid as bin_id,
           btrim(raw.label->>'box_no') as box_code,
           nullif(btrim(coalesce(raw.label->>'floor', '')), '') as floor,
           raw.label->'imeis' as imeis
    from raw_labels raw
  ),
  parsed_items as (
    select label.label_order,
           raw_imei.ordinality as imei_order,
           label.bin_id,
           label.box_code,
           label.floor,
           raw_imei.value as imei
    from parsed_labels label
    cross join lateral jsonb_array_elements_text(label.imeis)
      with ordinality as raw_imei(value, ordinality)
  ),
  ranked_items as (
    select parsed.*,
           row_number() over (
             partition by parsed.imei
             order by parsed.label_order, parsed.imei_order
           ) as imei_rank
    from parsed_items parsed
  ),
  new_items as (
    select ranked.*
    from ranked_items ranked
    left join public.items existing on existing.imei = ranked.imei
    where ranked.imei_rank = 1
      and existing.imei is null
  ),
  desired_boxes as (
    select distinct on (item.bin_id, item.box_code)
           item.bin_id,
           item.box_code,
           item.floor
    from new_items item
    order by item.bin_id, item.box_code, item.label_order desc
  ),
  inserted_boxes as (
    insert into public.boxes (bin_id, box_code, floor)
    select desired.bin_id, desired.box_code, desired.floor
    from desired_boxes desired
    on conflict (bin_id, box_code) do nothing
    returning id
  )
  select (select count(*) from desired_boxes),
         (select count(*) from inserted_boxes)
  into v_desired_boxes, v_created_boxes;

  v_reused_boxes := v_desired_boxes - v_created_boxes;

  with raw_labels as (
    select entry.ordinality as label_order,
           entry.label
    from jsonb_array_elements(p_labels)
      with ordinality as entry(label, ordinality)
  ),
  parsed_labels as (
    select raw.label_order,
           (raw.label->>'device_id')::uuid as bin_id,
           btrim(raw.label->>'box_no') as box_code,
           nullif(btrim(coalesce(raw.label->>'floor', '')), '') as floor,
           raw.label->'imeis' as imeis
    from raw_labels raw
  ),
  parsed_items as (
    select label.label_order,
           raw_imei.ordinality as imei_order,
           label.bin_id,
           label.box_code,
           label.floor,
           raw_imei.value as imei
    from parsed_labels label
    cross join lateral jsonb_array_elements_text(label.imeis)
      with ordinality as raw_imei(value, ordinality)
  ),
  ranked_items as (
    select parsed.*,
           row_number() over (
             partition by parsed.imei
             order by parsed.label_order, parsed.imei_order
           ) as imei_rank
    from parsed_items parsed
  ),
  new_items as (
    select ranked.*
    from ranked_items ranked
    left join public.items existing on existing.imei = ranked.imei
    where ranked.imei_rank = 1
      and existing.imei is null
  ),
  desired_boxes as (
    select distinct on (item.bin_id, item.box_code)
           item.bin_id,
           item.box_code,
           item.floor
    from new_items item
    order by item.bin_id, item.box_code, item.label_order desc
  )
  update public.boxes box
  set floor = desired.floor
  from desired_boxes desired
  where box.bin_id = desired.bin_id
    and box.box_code = desired.box_code
    and desired.floor is not null
    and box.floor is distinct from desired.floor;

  with raw_labels as (
    select entry.ordinality as label_order,
           entry.label
    from jsonb_array_elements(p_labels)
      with ordinality as entry(label, ordinality)
  ),
  parsed_labels as (
    select raw.label_order,
           (raw.label->>'device_id')::uuid as bin_id,
           btrim(raw.label->>'box_no') as box_code,
           raw.label->'imeis' as imeis
    from raw_labels raw
  ),
  parsed_items as (
    select label.label_order,
           raw_imei.ordinality as imei_order,
           label.bin_id,
           label.box_code,
           raw_imei.value as imei
    from parsed_labels label
    cross join lateral jsonb_array_elements_text(label.imeis)
      with ordinality as raw_imei(value, ordinality)
  ),
  ranked_items as (
    select parsed.*,
           row_number() over (
             partition by parsed.imei
             order by parsed.label_order, parsed.imei_order
           ) as imei_rank
    from parsed_items parsed
  ),
  new_items as (
    select ranked.*
    from ranked_items ranked
    left join public.items existing on existing.imei = ranked.imei
    where ranked.imei_rank = 1
      and existing.imei is null
  ),
  inserted_items as (
    insert into public.items (
      imei,
      box_id,
      device_id,
      status,
      imported_at,
      imported_by,
      import_id
    )
    select item.imei,
           box.id,
           item.bin_id,
           'IN',
           v_now,
           p_actor_id,
           v_batch_id
    from new_items item
    join public.boxes box
      on box.bin_id = item.bin_id
     and box.box_code = item.box_code
    returning item_id, imei, box_id, device_id
  ),
  inserted_movements as (
    insert into public.movements (
      type,
      operation_id,
      batch_id,
      item_id,
      box_id,
      device_id,
      imei,
      qty,
      actor,
      actor_id,
      created_by,
      created_at,
      source,
      shipment_ref,
      notes
    )
    select 'IN',
           p_operation_id,
           v_batch_id,
           item.item_id,
           item.box_id,
           item.device_id,
           item.imei,
           1,
           btrim(p_actor),
           p_actor_id,
           p_actor_id,
           v_now,
           p_source,
           nullif(btrim(coalesce(p_shipment_ref, '')), ''),
           case
             when nullif(btrim(coalesce(p_vendor, '')), '') is not null
             then 'vendor=' || btrim(p_vendor)
             else null
           end
    from inserted_items item
    returning movement_id
  )
  select count(*)
  into v_inserted_imeis
  from inserted_movements;

  if v_inserted_imeis <> v_new_imeis then
    raise exception 'INBOUND_INSERT_COUNT_MISMATCH' using errcode = '40001';
  end if;

  -- Accessories delivered in the boxes of the devices just received
  -- (Inventory Setup > Included at inbound), unless unticked at preview.
  -- Only newly received devices count; IMEIs already in stock add nothing.
  for v_included in
    select rule.id as rule_id,
           rule.accessory_bin_id,
           accessory.name as accessory_name,
           device.name as device_name,
           count(item.item_id)::integer as devices,
           (count(item.item_id) * rule.quantity)::integer as qty
    from public.items item
    join public.device_inbound_accessories rule on rule.device_id = item.device_id
    join public.accessory_bins accessory
      on accessory.id = rule.accessory_bin_id
     and accessory.active
    join public.bins device on device.id = item.device_id
    where item.import_id = v_batch_id
      and not (rule.id = any(coalesce(p_skip_included_accessories, '{}'::uuid[])))
    group by rule.id, rule.accessory_bin_id, accessory.name, device.name, rule.quantity
    order by rule.accessory_bin_id, rule.id
  loop
    update public.accessory_bins
    set current_stock = coalesce(current_stock, 0) + v_included.qty
    where id = v_included.accessory_bin_id
    returning current_stock into v_accessory_stock;

    insert into public.accessory_movements (
      accessory_bin_id,
      qty,
      movement_type,
      shipment_ref,
      note,
      actor,
      actor_id,
      source,
      operation_id
    )
    values (
      v_included.accessory_bin_id,
      v_included.qty,
      'IN',
      nullif(btrim(coalesce(p_shipment_ref, '')), ''),
      format('Included with %s × %s', v_included.devices, v_included.device_name),
      btrim(p_actor),
      p_actor_id,
      'inbound',
      p_operation_id
    );

    v_included_accessories := v_included_accessories || jsonb_build_array(
      jsonb_build_object(
        'rule_id', v_included.rule_id,
        'accessory_bin_id', v_included.accessory_bin_id,
        'accessory', v_included.accessory_name,
        'device', v_included.device_name,
        'devices', v_included.devices,
        'qty', v_included.qty,
        'after_stock', v_accessory_stock
      )
    );
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'batch_id', v_batch_id,
    'created_at', v_batch_created_at,
    'totals', jsonb_build_object(
      'inserted_imeis', v_inserted_imeis,
      'skipped_existing_imeis', v_existing_imeis,
      'created_boxes', v_created_boxes,
      'reused_boxes', v_reused_boxes
    ),
    'included_accessories', v_included_accessories
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_outbound_batch(p_imeis text[], p_actor text, p_actor_id uuid, p_shipment_ref text, p_source text, p_operation_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_inserted integer;
  v_updated integer;
  v_result jsonb;
  v_imei text;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'OUTBOUND_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if coalesce(cardinality(p_imeis), 0) not between 1 and 50000
    or p_source not in ('manual', 'excel')
    or char_length(coalesce(p_shipment_ref, '')) > 500
    or exists (
      select 1
      from unnest(p_imeis) as requested(imei)
      where requested.imei !~ '^([0-9]{15}|[0-9]{12})$'
    ) then
    raise exception 'OUTBOUND_REQUEST_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'outbound',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'outbound'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result::json;
  end if;

  select count(distinct requested.imei)
  into v_requested_count
  from unnest(p_imeis) as requested(imei);

  for v_imei in
    select distinct requested.imei
    from unnest(p_imeis) as requested(imei)
    order by requested.imei
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_imei, 735642));
  end loop;

  perform item.item_id
  from public.items item
  where item.imei = any(p_imeis)
  order by item.item_id
  for update of item;

  select count(*)
  into v_found_count
  from public.items item
  where item.imei = any(p_imeis);

  if v_found_count <> v_requested_count then
    raise exception 'OUTBOUND_IMEIS_NOT_FOUND' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.items item
    where item.imei = any(p_imeis)
      and item.status <> 'IN'
  ) then
    raise exception 'OUTBOUND_IMEI_NOT_IN_STOCK' using errcode = '23514';
  end if;

  -- 12-digit serial numbers leave only from the MatrixIQ bin.
  if exists (
    select 1
    from public.items item
    left join public.bins bin on bin.id = item.device_id
    where item.imei = any(p_imeis)
      and char_length(item.imei) = 12
      and item.imei !~ public.stockpro_device_id_pattern(bin.name)
  ) then
    raise exception 'OUTBOUND_REQUEST_INVALID' using errcode = '22023';
  end if;

  insert into public.movements (
    type,
    imei,
    item_id,
    device_id,
    box_id,
    operation_id,
    actor,
    actor_id,
    source,
    shipment_ref,
    created_by,
    created_at,
    qty
  )
  select
    'OUT',
    item.imei,
    item.item_id,
    item.device_id,
    item.box_id,
    p_operation_id,
    btrim(p_actor),
    p_actor_id,
    p_source,
    nullif(btrim(coalesce(p_shipment_ref, '')), ''),
    p_actor_id,
    v_now,
    1
  from public.items item
  where item.imei = any(p_imeis)
  order by item.item_id;

  get diagnostics v_inserted = row_count;

  if v_inserted <> v_requested_count then
    raise exception 'OUTBOUND_MOVEMENT_COUNT_MISMATCH' using errcode = '40001';
  end if;

  update public.items item
  set status = 'OUT',
      shipped_at = v_now,
      shipment_ref = nullif(btrim(coalesce(p_shipment_ref, '')), '')
  where item.imei = any(p_imeis)
    and item.status = 'IN';

  get diagnostics v_updated = row_count;

  if v_updated <> v_requested_count then
    raise exception 'OUTBOUND_ITEM_STATE_CHANGED' using errcode = '40001';
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'count', v_updated
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result::json;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_item record;
  v_box_id uuid;
  v_box_inserted integer;
  v_updated integer;
  v_returned integer := 0;
  v_created_boxes integer := 0;
  v_reused_boxes integer := 0;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null or p_actor_id is null or nullif(btrim(p_actor), '') is null then
    raise exception 'RETURN_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if coalesce(cardinality(p_item_ids), 0) not between 1 and 500 then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if nullif(btrim(p_target_box), '') is null
    or char_length(btrim(p_target_box)) > 200 then
    raise exception 'RETURN_TARGET_BOX_INVALID' using errcode = '22023';
  end if;

  if char_length(coalesce(p_target_floor, '')) > 50
    or nullif(btrim(p_return_type), '') is null
    or char_length(btrim(p_return_type)) > 200
    or nullif(btrim(p_return_reason), '') is null
    or char_length(btrim(p_return_reason)) > 1000
    or char_length(coalesce(p_return_ref, '')) > 500 then
    raise exception 'RETURN_METADATA_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'return',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select r.command_type, r.actor_id, r.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts r
    where r.operation_id = p_operation_id;

    if v_existing_command is distinct from 'return'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select count(distinct requested.item_id)
  into v_requested_count
  from unnest(p_item_ids) as requested(item_id);

  perform i.item_id
  from public.items i
  where i.item_id = any(p_item_ids)
  order by i.item_id
  for update of i;

  select count(*)
  into v_found_count
  from public.items i
  where i.item_id = any(p_item_ids);

  if v_found_count <> v_requested_count then
    raise exception 'RETURN_ITEMS_NOT_FOUND' using errcode = 'P0002';
  end if;

  for v_item in
    select i.item_id, i.imei, i.device_id, i.status
    from public.items i
    where i.item_id = any(p_item_ids)
    order by i.item_id
    for update of i
  loop
    if upper(v_item.status) <> 'OUT' then
      continue;
    end if;

    if v_item.device_id is null or nullif(v_item.imei, '') is null then
      raise exception 'RETURN_CANONICAL_ITEM_INVALID' using errcode = '23514';
    end if;

    insert into public.boxes (bin_id, box_code, floor)
    values (
      v_item.device_id,
      btrim(p_target_box),
      nullif(btrim(coalesce(p_target_floor, '')), '')
    )
    on conflict (bin_id, box_code) do nothing;

    get diagnostics v_box_inserted = row_count;

    select b.id
    into v_box_id
    from public.boxes b
    where b.bin_id = v_item.device_id
      and b.box_code = btrim(p_target_box)
    for update;

    if v_box_id is null then
      raise exception 'RETURN_TARGET_BOX_UNAVAILABLE' using errcode = 'P0002';
    end if;

    if nullif(btrim(coalesce(p_target_floor, '')), '') is not null then
      update public.boxes
      set floor = btrim(p_target_floor)
      where id = v_box_id
        and floor is distinct from btrim(p_target_floor);
    end if;

    update public.items
    set status = 'IN',
        box_id = v_box_id
    where item_id = v_item.item_id
      and status = 'OUT';

    get diagnostics v_updated = row_count;

    if v_updated <> 1 then
      raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
    end if;

    insert into public.movements (
      type,
      operation_id,
      item_id,
      box_id,
      device_id,
      imei,
      qty,
      actor,
      actor_id,
      created_by,
      created_at,
      shipment_ref,
      source,
      return_type,
      return_reason,
      notes
    )
    values (
      'RETURN',
      p_operation_id,
      v_item.item_id,
      v_box_id,
      v_item.device_id,
      v_item.imei,
      1,
      btrim(p_actor),
      p_actor_id,
      p_actor_id,
      v_now,
      nullif(btrim(coalesce(p_return_ref, '')), ''),
      'customer_return',
      btrim(p_return_type),
      btrim(p_return_reason),
      btrim(p_return_type) || ' - ' || btrim(p_return_reason)
    );

    v_returned := v_returned + 1;
    if v_box_inserted = 1 then
      v_created_boxes := v_created_boxes + 1;
    else
      v_reused_boxes := v_reused_boxes + 1;
    end if;
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'returned', v_returned,
    'created_boxes', v_created_boxes,
    'reused_boxes', v_reused_boxes
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_item record;
  v_target_box_id uuid;
  v_movement_box_id uuid;
  v_movement_id uuid;
  v_box_inserted integer;
  v_updated integer;
  v_recorded integer := 0;
  v_added_to_stock integer := 0;
  v_logged_only integer := 0;
  v_created_boxes integer := 0;
  v_reused_boxes integer := 0;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
  v_status text := lower(btrim(coalesce(p_return_status, '')));
  v_courier text := upper(btrim(coalesce(p_courier, '')));
  v_country_code text := upper(btrim(coalesce(p_country_code, '')));
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'RETURN_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if coalesce(cardinality(p_item_ids), 0) not between 1 and 500 then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if v_status not in ('available', 'damaged', 'returned_unprocessed')
    or v_courier not in ('DHL', 'EASYPOST')
    or v_country_code not in ('BE', 'UK', 'NL', 'DE', 'FR', 'ES', 'IE', 'PT', 'IT')
    or nullif(btrim(p_return_ref), '') is null
    or char_length(btrim(p_return_ref)) > 200
    or nullif(btrim(p_customer), '') is null
    or char_length(btrim(p_customer)) > 300
    or nullif(btrim(p_sur_id), '') is null
    or char_length(btrim(p_sur_id)) > 200
    or nullif(btrim(coalesce(p_return_type, '')), '') is null
    or btrim(p_return_type) not in ('cancellation_stop', 'technical_stop')
    or nullif(btrim(p_return_reason), '') is null
    or char_length(btrim(p_return_reason)) > 1000 then
    raise exception 'RETURN_METADATA_INVALID' using errcode = '22023';
  end if;

  if v_status = 'available' and (
    nullif(btrim(coalesce(p_target_box, '')), '') is null
    or char_length(btrim(p_target_box)) > 200
    or btrim(coalesce(p_target_floor, '')) not in ('00', '1', '6', 'Cabinet')
  ) then
    raise exception 'RETURN_TARGET_BOX_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'return',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select r.command_type, r.actor_id, r.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts r
    where r.operation_id = p_operation_id;

    if v_existing_command is distinct from 'return'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select count(distinct requested.item_id)
  into v_requested_count
  from unnest(p_item_ids) as requested(item_id);

  perform i.item_id
  from public.items i
  where i.item_id = any(p_item_ids)
  order by i.item_id
  for update of i;

  select count(*)
  into v_found_count
  from public.items i
  where i.item_id = any(p_item_ids);

  if v_found_count <> v_requested_count then
    raise exception 'RETURN_ITEMS_NOT_FOUND' using errcode = 'P0002';
  end if;

  for v_item in
    select
      i.item_id,
      i.imei,
      i.device_id,
      i.status,
      i.box_id,
      coalesce(b.box_code, '') as previous_box,
      coalesce(b.floor, '') as previous_floor
    from public.items i
    left join public.boxes b on b.id = i.box_id
    where i.item_id = any(p_item_ids)
    order by i.item_id
    for update of i
  loop
    if upper(v_item.status) <> 'OUT' then
      raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
    end if;

    if v_item.device_id is null or nullif(v_item.imei, '') is null then
      raise exception 'RETURN_CANONICAL_ITEM_INVALID' using errcode = '23514';
    end if;

    v_target_box_id := null;
    v_box_inserted := 0;

    if v_status = 'available' then
      insert into public.boxes (bin_id, box_code, floor)
      values (
        v_item.device_id,
        btrim(p_target_box),
        btrim(p_target_floor)
      )
      on conflict (bin_id, box_code) do nothing;

      get diagnostics v_box_inserted = row_count;

      select b.id
      into v_target_box_id
      from public.boxes b
      where b.bin_id = v_item.device_id
        and b.box_code = btrim(p_target_box)
      for update;

      if v_target_box_id is null then
        raise exception 'RETURN_TARGET_BOX_UNAVAILABLE' using errcode = 'P0002';
      end if;

      update public.boxes
      set floor = btrim(p_target_floor)
      where id = v_target_box_id
        and floor is distinct from btrim(p_target_floor);

      update public.items
      set status = 'IN',
          box_id = v_target_box_id
      where item_id = v_item.item_id
        and status = 'OUT';

      get diagnostics v_updated = row_count;

      if v_updated <> 1 then
        raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
      end if;

      v_movement_box_id := v_target_box_id;
      v_added_to_stock := v_added_to_stock + 1;
      if v_box_inserted = 1 then
        v_created_boxes := v_created_boxes + 1;
      else
        v_reused_boxes := v_reused_boxes + 1;
      end if;
    else
      v_movement_box_id := v_item.box_id;
      v_logged_only := v_logged_only + 1;
    end if;

    insert into public.movements (
      type,
      operation_id,
      item_id,
      box_id,
      device_id,
      imei,
      qty,
      actor,
      actor_id,
      created_by,
      created_at,
      shipment_ref,
      source,
      return_type,
      return_reason,
      notes
    )
    values (
      'RETURN',
      p_operation_id,
      v_item.item_id,
      v_movement_box_id,
      v_item.device_id,
      v_item.imei,
      1,
      btrim(p_actor),
      p_actor_id,
      p_actor_id,
      v_now,
      btrim(p_return_ref),
      'customer_return',
      btrim(p_return_type),
      btrim(p_return_reason),
      'status=' || v_status || '; ' || btrim(p_return_type) || ' - ' || btrim(p_return_reason)
    )
    returning movement_id into v_movement_id;

    insert into public.return_records (
      movement_id,
      operation_id,
      created_at,
      actor,
      actor_id,
      item_id,
      imei,
      device_id,
      return_ref,
      customer,
      sur_id,
      courier,
      country_code,
      return_status,
      return_type,
      return_reason,
      previous_box,
      previous_floor,
      target_box,
      target_floor,
      stock_action
    )
    values (
      v_movement_id,
      p_operation_id,
      v_now,
      btrim(p_actor),
      p_actor_id,
      v_item.item_id,
      v_item.imei,
      v_item.device_id,
      btrim(p_return_ref),
      btrim(p_customer),
      btrim(p_sur_id),
      v_courier,
      v_country_code,
      v_status,
      btrim(p_return_type),
      btrim(p_return_reason),
      v_item.previous_box,
      v_item.previous_floor,
      case when v_status = 'available' then btrim(p_target_box) else null end,
      case when v_status = 'available' then btrim(p_target_floor) else null end,
      case when v_status = 'available' then 'added_to_stock' else 'no_stock_change' end
    );

    v_recorded := v_recorded + 1;
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'created_at', v_now,
    'return_status', v_status,
    'recorded', v_recorded,
    'returned', v_added_to_stock,
    'added_to_stock', v_added_to_stock,
    'logged_only', v_logged_only,
    'created_boxes', v_created_boxes,
    'reused_boxes', v_reused_boxes
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_item record;
  v_target_box_id uuid;
  v_movement_box_id uuid;
  v_movement_id uuid;
  v_box_inserted integer;
  v_updated integer;
  v_recorded integer := 0;
  v_added_to_stock integer := 0;
  v_logged_only integer := 0;
  v_created_boxes integer := 0;
  v_reused_boxes integer := 0;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
  v_status text := lower(btrim(coalesce(p_return_status, '')));
  v_courier text := upper(btrim(coalesce(p_courier, '')));
  v_country_code text := upper(btrim(coalesce(p_country_code, '')));
  v_requested_device text := nullif(btrim(coalesce(p_reported_device, '')), '');
  v_reported_device text;
  v_record_device text;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'RETURN_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if coalesce(cardinality(p_item_ids), 0) not between 1 and 500 then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if v_status not in ('available', 'damaged', 'disposed', 'returned_unprocessed')
    or v_courier not in ('DHL', 'EASYPOST')
    or v_country_code not in ('BE', 'UK', 'NL', 'DE', 'FR', 'ES', 'IE', 'PT', 'IT')
    or nullif(btrim(p_return_ref), '') is null
    or char_length(btrim(p_return_ref)) > 200
    or nullif(btrim(p_customer), '') is null
    or char_length(btrim(p_customer)) > 300
    or nullif(btrim(p_sur_id), '') is null
    or char_length(btrim(p_sur_id)) > 200
    or nullif(btrim(coalesce(p_return_type, '')), '') is null
    or btrim(p_return_type) not in ('cancellation_stop', 'technical_stop')
    or nullif(btrim(p_return_reason), '') is null
    or char_length(btrim(p_return_reason)) > 1000 then
    raise exception 'RETURN_METADATA_INVALID' using errcode = '22023';
  end if;

  if v_status = 'available' and (
    nullif(btrim(coalesce(p_target_box, '')), '') is null
    or char_length(btrim(p_target_box)) > 200
    or btrim(coalesce(p_target_floor, '')) not in ('00', '1', '6', 'Cabinet')
  ) then
    raise exception 'RETURN_TARGET_BOX_INVALID' using errcode = '22023';
  end if;

  if v_status <> 'available' then
    if v_requested_device is null or char_length(v_requested_device) > 200 then
      raise exception 'RETURN_DEVICE_INVALID' using errcode = '22023';
    end if;

    select b.name
    into v_reported_device
    from public.bins b
    where lower(btrim(b.name)) = lower(v_requested_device)
    order by b.active desc, b.name
    limit 1;

    if v_reported_device is null then
      v_reported_device := case upper(v_requested_device)
        when 'LMU2640' then 'LMU2640'
        when 'FMT100' then 'FMT100'
        when 'FMB020' then 'FMB020'
        when 'FMB003' then 'FMB003'
        when 'FMB920' then 'FMB920'
        when 'FMB130' then 'FMB130'
        when 'GL50B' then 'GL50B'
        when 'FMB640' then 'FMB640'
        when 'FMB641' then 'FMB641'
        when 'FMB204' then 'FMB204'
        when 'BADAI' then 'Badai'
        else null
      end;
    end if;

    if v_reported_device is null then
      raise exception 'RETURN_DEVICE_INVALID' using errcode = '22023';
    end if;
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'return',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select r.command_type, r.actor_id, r.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts r
    where r.operation_id = p_operation_id;

    if v_existing_command is distinct from 'return'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select count(distinct requested.item_id)
  into v_requested_count
  from unnest(p_item_ids) as requested(item_id);

  perform i.item_id
  from public.items i
  where i.item_id = any(p_item_ids)
  order by i.item_id
  for update of i;

  select count(*)
  into v_found_count
  from public.items i
  where i.item_id = any(p_item_ids);

  if v_found_count <> v_requested_count then
    raise exception 'RETURN_ITEMS_NOT_FOUND' using errcode = 'P0002';
  end if;

  for v_item in
    select
      i.item_id,
      i.imei,
      i.device_id,
      i.status,
      i.box_id,
      coalesce(previous_box.box_code, '') as previous_box,
      coalesce(previous_box.floor, '') as previous_floor,
      coalesce(canonical_bin.name, '') as canonical_device
    from public.items i
    left join public.boxes previous_box on previous_box.id = i.box_id
    left join public.bins canonical_bin on canonical_bin.id = i.device_id
    where i.item_id = any(p_item_ids)
    order by i.item_id
    for update of i
  loop
    if upper(v_item.status) <> 'OUT' then
      raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
    end if;

    if v_item.device_id is null
      or nullif(v_item.imei, '') is null
      or nullif(v_item.canonical_device, '') is null then
      raise exception 'RETURN_CANONICAL_ITEM_INVALID' using errcode = '23514';
    end if;

    v_record_device := case
      when v_status = 'available' then v_item.canonical_device
      else v_reported_device
    end;
    v_target_box_id := null;
    v_box_inserted := 0;

    if v_status = 'available' then
      insert into public.boxes (bin_id, box_code, floor)
      values (
        v_item.device_id,
        btrim(p_target_box),
        btrim(p_target_floor)
      )
      on conflict (bin_id, box_code) do nothing;

      get diagnostics v_box_inserted = row_count;

      select b.id
      into v_target_box_id
      from public.boxes b
      where b.bin_id = v_item.device_id
        and b.box_code = btrim(p_target_box)
      for update;

      if v_target_box_id is null then
        raise exception 'RETURN_TARGET_BOX_UNAVAILABLE' using errcode = 'P0002';
      end if;

      update public.boxes
      set floor = btrim(p_target_floor)
      where id = v_target_box_id
        and floor is distinct from btrim(p_target_floor);

      update public.items
      set status = 'IN',
          box_id = v_target_box_id
      where item_id = v_item.item_id
        and status = 'OUT';

      get diagnostics v_updated = row_count;

      if v_updated <> 1 then
        raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
      end if;

      v_movement_box_id := v_target_box_id;
      v_added_to_stock := v_added_to_stock + 1;
      if v_box_inserted = 1 then
        v_created_boxes := v_created_boxes + 1;
      else
        v_reused_boxes := v_reused_boxes + 1;
      end if;
    else
      v_movement_box_id := v_item.box_id;
      v_logged_only := v_logged_only + 1;
    end if;

    insert into public.movements (
      type,
      operation_id,
      item_id,
      box_id,
      device_id,
      imei,
      qty,
      actor,
      actor_id,
      created_by,
      created_at,
      shipment_ref,
      source,
      return_type,
      return_reason,
      notes
    )
    values (
      'RETURN',
      p_operation_id,
      v_item.item_id,
      v_movement_box_id,
      v_item.device_id,
      v_item.imei,
      1,
      btrim(p_actor),
      p_actor_id,
      p_actor_id,
      v_now,
      btrim(p_return_ref),
      'customer_return',
      btrim(p_return_type),
      btrim(p_return_reason),
      'status=' || v_status || '; device=' || v_record_device || '; '
        || btrim(p_return_type) || ' - ' || btrim(p_return_reason)
    )
    returning movement_id into v_movement_id;

    insert into public.return_records (
      movement_id,
      operation_id,
      created_at,
      actor,
      actor_id,
      item_id,
      imei,
      device_id,
      reported_device,
      return_ref,
      customer,
      sur_id,
      courier,
      country_code,
      return_status,
      return_type,
      return_reason,
      previous_box,
      previous_floor,
      target_box,
      target_floor,
      stock_action
    )
    values (
      v_movement_id,
      p_operation_id,
      v_now,
      btrim(p_actor),
      p_actor_id,
      v_item.item_id,
      v_item.imei,
      v_item.device_id,
      v_record_device,
      btrim(p_return_ref),
      btrim(p_customer),
      btrim(p_sur_id),
      v_courier,
      v_country_code,
      v_status,
      btrim(p_return_type),
      btrim(p_return_reason),
      v_item.previous_box,
      v_item.previous_floor,
      case when v_status = 'available' then btrim(p_target_box) else null end,
      case when v_status = 'available' then btrim(p_target_floor) else null end,
      case when v_status = 'available' then 'added_to_stock' else 'no_stock_change' end
    );

    v_recorded := v_recorded + 1;
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'created_at', v_now,
    'return_status', v_status,
    'reported_device', case when v_status = 'available' then null else v_reported_device end,
    'recorded', v_recorded,
    'returned', v_added_to_stock,
    'added_to_stock', v_added_to_stock,
    'logged_only', v_logged_only,
    'created_boxes', v_created_boxes,
    'reused_boxes', v_reused_boxes
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch_v2(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text, p_unknown_imeis text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_known_count integer;
  v_unknown_count integer;
  v_unknown_inserted integer := 0;
  v_unknown_imei text;
  v_unknown_imeis text[] := array[]::text[];
  v_status text := lower(btrim(coalesce(p_return_status, '')));
  v_courier text := upper(btrim(coalesce(p_courier, '')));
  v_country_code text := upper(btrim(coalesce(p_country_code, '')));
  v_requested_device text := nullif(btrim(coalesce(p_reported_device, '')), '');
  v_reported_device text;
  v_known_result jsonb;
  v_created_at timestamptz := clock_timestamp();
  v_recorded integer := 0;
  v_added_to_stock integer := 0;
  v_logged_only integer := 0;
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'RETURN_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  select count(distinct requested.item_id)
  into v_known_count
  from unnest(coalesce(p_item_ids, array[]::uuid[])) as requested(item_id)
  where requested.item_id is not null;

  select coalesce(array_agg(candidate.imei order by candidate.imei), array[]::text[])
  into v_unknown_imeis
  from (
    select distinct btrim(raw.imei) as imei
    from unnest(coalesce(p_unknown_imeis, array[]::text[])) as raw(imei)
    where nullif(btrim(raw.imei), '') is not null
  ) candidate;

  v_unknown_count := cardinality(v_unknown_imeis);

  if v_known_count + v_unknown_count not between 1 and 500 then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if v_status not in ('available', 'damaged', 'disposed', 'returned_unprocessed')
    or v_courier not in ('DHL', 'EASYPOST')
    or v_country_code not in ('BE', 'UK', 'NL', 'DE', 'FR', 'ES', 'IE', 'PT', 'IT')
    or nullif(btrim(p_return_ref), '') is null
    or char_length(btrim(p_return_ref)) > 200
    or nullif(btrim(p_customer), '') is null
    or char_length(btrim(p_customer)) > 300
    or nullif(btrim(p_sur_id), '') is null
    or char_length(btrim(p_sur_id)) > 200
    or btrim(coalesce(p_return_type, '')) not in ('cancellation_stop', 'technical_stop')
    or nullif(btrim(p_return_reason), '') is null
    or char_length(btrim(p_return_reason)) > 1000 then
    raise exception 'RETURN_METADATA_INVALID' using errcode = '22023';
  end if;

  if v_status = 'available' and v_unknown_count > 0 then
    raise exception 'RETURN_UNKNOWN_AVAILABLE_ITEM' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from unnest(v_unknown_imeis) as requested(imei)
    where requested.imei !~ '^[0-9]{15}$'
  ) then
    raise exception 'RETURN_IMEI_INVALID' using errcode = '22023';
  end if;

  if v_status <> 'available' then
    if v_requested_device is null or char_length(v_requested_device) > 200 then
      raise exception 'RETURN_DEVICE_INVALID' using errcode = '22023';
    end if;

    select b.name
    into v_reported_device
    from public.bins b
    where lower(btrim(b.name)) = lower(v_requested_device)
    order by b.active desc, b.name
    limit 1;

    if v_reported_device is null then
      v_reported_device := case upper(v_requested_device)
        when 'LMU2640' then 'LMU2640'
        when 'FMT100' then 'FMT100'
        when 'FMB020' then 'FMB020'
        when 'FMB003' then 'FMB003'
        when 'FMB920' then 'FMB920'
        when 'FMB130' then 'FMB130'
        when 'GL50B' then 'GL50B'
        when 'FMB640' then 'FMB640'
        when 'FMB641' then 'FMB641'
        when 'FMB204' then 'FMB204'
        when 'BADAI' then 'Badai'
        else null
      end;
    end if;

    if v_reported_device is null then
      raise exception 'RETURN_DEVICE_INVALID' using errcode = '22023';
    end if;
  end if;

  -- An IMEI classified as unknown during preview must still be absent at
  -- confirmation time. If it appeared meanwhile, the operator must preview
  -- again so canonical data cannot be bypassed.
  if v_unknown_count > 0 and exists (
    select 1
    from public.items i
    where i.imei = any(v_unknown_imeis)
  ) then
    raise exception 'RETURN_ITEM_STATE_CHANGED' using errcode = '40001';
  end if;

  select receipt.command_type, receipt.actor_id, receipt.result
  into v_existing_command, v_existing_actor, v_existing_result
  from public.inventory_command_receipts receipt
  where receipt.operation_id = p_operation_id;

  if found then
    if v_existing_command is distinct from 'return'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;
    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;
    return v_existing_result;
  end if;

  if v_known_count > 0 then
    select public.confirm_return_batch(
      p_operation_id,
      p_actor_id,
      p_actor,
      p_item_ids,
      p_target_box,
      p_target_floor,
      p_return_ref,
      p_return_type,
      p_return_reason,
      p_return_status,
      p_courier,
      p_country_code,
      p_customer,
      p_sur_id,
      p_reported_device
    )
    into v_known_result;

    v_created_at := coalesce(
      (v_known_result ->> 'created_at')::timestamptz,
      v_created_at
    );
  else
    insert into public.inventory_command_receipts (
      operation_id,
      command_type,
      actor_id
    )
    values (
      p_operation_id,
      'return',
      p_actor_id
    )
    on conflict (operation_id) do nothing;

    get diagnostics v_receipt_inserted = row_count;

    if v_receipt_inserted = 0 then
      select receipt.command_type, receipt.actor_id, receipt.result
      into v_existing_command, v_existing_actor, v_existing_result
      from public.inventory_command_receipts receipt
      where receipt.operation_id = p_operation_id;

      if v_existing_command is distinct from 'return'
        or v_existing_actor is distinct from p_actor_id then
        raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
      end if;
      if v_existing_result is null then
        raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
      end if;
      return v_existing_result;
    end if;
  end if;

  foreach v_unknown_imei in array v_unknown_imeis
  loop
    insert into public.return_records (
      movement_id,
      operation_id,
      created_at,
      actor,
      actor_id,
      item_id,
      imei,
      device_id,
      reported_device,
      return_ref,
      customer,
      sur_id,
      courier,
      country_code,
      return_status,
      return_type,
      return_reason,
      previous_box,
      previous_floor,
      target_box,
      target_floor,
      stock_action
    )
    values (
      null,
      p_operation_id,
      v_created_at,
      btrim(p_actor),
      p_actor_id,
      null,
      v_unknown_imei,
      null,
      v_reported_device,
      btrim(p_return_ref),
      btrim(p_customer),
      btrim(p_sur_id),
      v_courier,
      v_country_code,
      v_status,
      btrim(p_return_type),
      btrim(p_return_reason),
      '',
      '',
      null,
      null,
      'no_stock_change'
    )
    on conflict (operation_id, imei)
      where operation_id is not null
      do nothing;

    get diagnostics v_receipt_inserted = row_count;
    v_unknown_inserted := v_unknown_inserted + v_receipt_inserted;
  end loop;

  select
    count(*)::integer,
    count(*) filter (where records.stock_action = 'added_to_stock')::integer,
    count(*) filter (where records.stock_action = 'no_stock_change')::integer
  into v_recorded, v_added_to_stock, v_logged_only
  from public.return_records records
  where records.operation_id = p_operation_id;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'created_at', v_created_at,
    'return_status', v_status,
    'reported_device', case when v_status = 'available' then null else v_reported_device end,
    'recorded', v_recorded,
    'returned', v_added_to_stock,
    'added_to_stock', v_added_to_stock,
    'logged_only', v_logged_only,
    'unknown_logged', v_unknown_inserted,
    'created_boxes', coalesce((v_known_result ->> 'created_boxes')::integer, 0),
    'reused_boxes', coalesce((v_known_result ->> 'reused_boxes')::integer, 0)
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch_v3(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_unknown_imeis text[], p_target_box text, p_target_floor text, p_return_ref text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_reason text := btrim(coalesce(p_return_reason, ''));
  v_forwarded_device text := p_reported_device;
  v_uses_lmu30g600_alias boolean := false;
  v_result jsonb;
begin
  if v_reason not in (
    'Returned device',
    'Other',
    'Fleet reductions/too many devices',
    'Replacement (wrong device/swap out)',
    'Service/Installation issues',
    'Moving to competitor/price',
    'Don''t see value',
    'Need more functionality',
    'Account Transfer',
    'Device Transfer',
    'Business Closure',
    'Returned to Sender',
    'Credit Stop – Fraud',
    'Credit Stop - Insolvency/administration',
    'Credit Stop – Non payer/exhausted all recoveries'
  ) then
    raise exception 'RETURN_REASON_INVALID' using errcode = '22023';
  end if;

  -- confirm_return_batch_v2 predates LMU30G600. If it has not been configured
  -- as a canonical bin yet, use an existing supported model only while the
  -- transaction runs, then immediately persist and return the requested model.
  v_uses_lmu30g600_alias :=
    lower(btrim(coalesce(p_return_status, ''))) <> 'available'
    and upper(btrim(coalesce(p_reported_device, ''))) = 'LMU30G600'
    and not exists (
      select 1
      from public.bins b
      where lower(btrim(b.name)) = 'lmu30g600'
    );

  if v_uses_lmu30g600_alias then
    v_forwarded_device := 'LMU2640';
  end if;

  select public.confirm_return_batch_v2(
    p_operation_id,
    p_actor_id,
    p_actor,
    p_item_ids,
    p_target_box,
    p_target_floor,
    p_return_ref,
    'technical_stop',
    v_reason,
    p_return_status,
    p_courier,
    p_country_code,
    p_customer,
    p_sur_id,
    v_forwarded_device,
    p_unknown_imeis
  )
  into v_result;

  if v_uses_lmu30g600_alias then
    update public.return_records r
    set reported_device = 'LMU30G600'
    where r.operation_id = p_operation_id;

    v_result := jsonb_set(
      v_result,
      '{reported_device}',
      to_jsonb('LMU30G600'::text),
      true
    );

    update public.inventory_command_receipts receipt
    set result = v_result
    where receipt.operation_id = p_operation_id
      and receipt.command_type = 'return';
  end if;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_return_batch_v4(p_operation_id uuid, p_actor_id uuid, p_actor text, p_items jsonb, p_target_box text, p_target_floor text, p_return_ref text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_item_ids uuid[] := array[]::uuid[];
  v_unknown_imeis text[] := array[]::text[];
  v_status text := lower(btrim(coalesce(p_return_status, '')));
  v_first_device text;
  v_single_device text;
  v_device_count integer := 0;
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'RETURN_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) not between 1 and 500 then
    raise exception 'RETURN_ITEM_LIMIT' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) as entry(item)
    where jsonb_typeof(entry.item) is distinct from 'object'
      or (
        nullif(entry.item ->> 'item_id', '') is null
        and nullif(entry.item ->> 'imei', '') is null
      )
      or (
        nullif(entry.item ->> 'item_id', '') is not null
        and (entry.item ->> 'item_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
      or (
        nullif(entry.item ->> 'imei', '') is not null
        and (entry.item ->> 'imei') !~ '^[0-9]{15}$'
      )
  ) then
    raise exception 'RETURN_ITEM_INVALID' using errcode = '22023';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_items)
  ) <> (
    select count(distinct coalesce(
      nullif(entry.item ->> 'item_id', ''),
      'imei:' || nullif(entry.item ->> 'imei', '')
    ))
    from jsonb_array_elements(p_items) as entry(item)
  ) then
    raise exception 'RETURN_ITEM_DUPLICATE' using errcode = '22023';
  end if;

  if v_status = 'available' and exists (
    select 1
    from jsonb_array_elements(p_items) as entry(item)
    where nullif(entry.item ->> 'item_id', '') is null
  ) then
    raise exception 'RETURN_UNKNOWN_AVAILABLE_ITEM' using errcode = 'P0002';
  end if;

  if v_status <> 'available' and exists (
    select 1
    from jsonb_array_elements(p_items) as entry(item)
    where public.resolve_return_device_name(
      entry.item ->> 'reported_device'
    ) is null
  ) then
    raise exception 'RETURN_DEVICE_INVALID' using errcode = '22023';
  end if;

  select receipt.command_type, receipt.actor_id, receipt.result
  into v_existing_command, v_existing_actor, v_existing_result
  from public.inventory_command_receipts receipt
  where receipt.operation_id = p_operation_id;

  if found then
    if v_existing_command is distinct from 'return'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;
    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;
    return v_existing_result;
  end if;

  select coalesce(
    array_agg(distinct (entry.item ->> 'item_id')::uuid),
    array[]::uuid[]
  )
  into v_item_ids
  from jsonb_array_elements(p_items) as entry(item)
  where nullif(entry.item ->> 'item_id', '') is not null;

  select coalesce(
    array_agg(distinct entry.item ->> 'imei'),
    array[]::text[]
  )
  into v_unknown_imeis
  from jsonb_array_elements(p_items) as entry(item)
  where nullif(entry.item ->> 'item_id', '') is null;

  if v_status <> 'available' then
    select public.resolve_return_device_name(
      entry.item ->> 'reported_device'
    )
    into v_first_device
    from jsonb_array_elements(p_items) as entry(item)
    limit 1;
  end if;

  select public.confirm_return_batch_v3(
    p_operation_id,
    p_actor_id,
    p_actor,
    v_item_ids,
    v_unknown_imeis,
    p_target_box,
    p_target_floor,
    p_return_ref,
    p_return_reason,
    p_return_status,
    p_courier,
    p_country_code,
    p_customer,
    p_sur_id,
    v_first_device
  )
  into v_result;

  if v_status <> 'available' then
    with requested as (
      select
        nullif(entry.item ->> 'item_id', '')::uuid as item_id,
        nullif(entry.item ->> 'imei', '') as imei,
        public.resolve_return_device_name(
          entry.item ->> 'reported_device'
        ) as reported_device
      from jsonb_array_elements(p_items) as entry(item)
    )
    update public.return_records records
    set reported_device = requested.reported_device
    from requested
    where records.operation_id = p_operation_id
      and (
        (requested.item_id is not null and records.item_id = requested.item_id)
        or (
          requested.item_id is null
          and requested.imei is not null
          and records.imei = requested.imei
        )
      );

    select
      count(distinct records.reported_device)::integer,
      min(records.reported_device)
    into v_device_count, v_single_device
    from public.return_records records
    where records.operation_id = p_operation_id;

    v_result := jsonb_set(
      v_result,
      '{reported_device}',
      case
        when v_device_count = 1 then to_jsonb(v_single_device)
        else 'null'::jsonb
      end,
      true
    );
    v_result := jsonb_set(
      v_result,
      '{device_count}',
      to_jsonb(v_device_count),
      true
    );

    update public.inventory_command_receipts receipt
    set result = v_result
    where receipt.operation_id = p_operation_id
      and receipt.command_type = 'return';
  end if;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.confirm_transfer_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_source_bin_id uuid, p_target_floor text, p_box_codes text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_requested_count integer;
  v_found_count integer;
  v_box record;
  v_moved integer := 0;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'TRANSFER_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if p_source_bin_id is null
    or nullif(btrim(p_target_floor), '') is null
    or char_length(btrim(p_target_floor)) > 50
    or coalesce(cardinality(p_box_codes), 0) not between 1 and 500
    or exists (
      select 1
      from unnest(p_box_codes) as requested(box_code)
      where nullif(btrim(requested.box_code), '') is null
        or char_length(btrim(requested.box_code)) > 200
    ) then
    raise exception 'TRANSFER_REQUEST_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'transfer',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'transfer'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select count(distinct btrim(requested.box_code))
  into v_requested_count
  from unnest(p_box_codes) as requested(box_code);

  perform box.id
  from public.boxes box
  where box.bin_id = p_source_bin_id
    and box.box_code in (
      select distinct btrim(requested.box_code)
      from unnest(p_box_codes) as requested(box_code)
    )
  order by box.id
  for update of box;

  select count(*)
  into v_found_count
  from public.boxes box
  where box.bin_id = p_source_bin_id
    and box.box_code in (
      select distinct btrim(requested.box_code)
      from unnest(p_box_codes) as requested(box_code)
    );

  if v_found_count <> v_requested_count then
    raise exception 'TRANSFER_BOXES_NOT_FOUND' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.boxes box
    where box.bin_id = p_source_bin_id
      and box.box_code in (
        select distinct btrim(requested.box_code)
        from unnest(p_box_codes) as requested(box_code)
      )
      and box.floor = btrim(p_target_floor)
  ) then
    raise exception 'TRANSFER_ALREADY_ON_FLOOR' using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.boxes box
    where box.bin_id = p_source_bin_id
      and box.box_code in (
        select distinct btrim(requested.box_code)
        from unnest(p_box_codes) as requested(box_code)
      )
      and not exists (
        select 1
        from public.items item
        where item.box_id = box.id
          and item.status = 'IN'
      )
  ) then
    raise exception 'TRANSFER_EMPTY_BOX' using errcode = '23514';
  end if;

  for v_box in
    select box.id, box.box_code, box.bin_id, box.floor
    from public.boxes box
    where box.bin_id = p_source_bin_id
      and box.box_code in (
        select distinct btrim(requested.box_code)
        from unnest(p_box_codes) as requested(box_code)
      )
    order by box.id
  loop
    update public.boxes
    set floor = btrim(p_target_floor)
    where id = v_box.id;

    insert into public.movements (
      type,
      operation_id,
      device_id,
      box_id,
      qty,
      actor,
      actor_id,
      created_by,
      from_floor,
      to_floor,
      created_at
    )
    values (
      'TRANSFER',
      p_operation_id,
      v_box.bin_id,
      v_box.id,
      1,
      btrim(p_actor),
      p_actor_id,
      p_actor_id,
      v_box.floor,
      btrim(p_target_floor),
      v_now
    );

    v_moved := v_moved + 1;
  end loop;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'moved_boxes', v_moved
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_supply_order(p_operation_id uuid, p_actor_id uuid, p_actor text, p_order_number text, p_from_office text, p_to_office text, p_comment text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_supply public.supplies%rowtype;
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null then
    raise exception 'SUPPLY_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(p_order_number), '') is null
    or char_length(btrim(p_order_number)) > 100
    or coalesce(p_from_office, '') !~ '^[A-Z]{2}$'
    or coalesce(p_to_office, '') !~ '^[A-Z]{2}$'
    or p_from_office = p_to_office
    or char_length(coalesce(p_comment, '')) > 2000
    or jsonb_typeof(p_items) is distinct from 'array'
    or jsonb_array_length(p_items) not between 1 and 500 then
    raise exception 'SUPPLY_CREATE_INVALID' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) as entry(item)
    where jsonb_typeof(entry.item) is distinct from 'object'
      or upper(coalesce(entry.item->>'product_type', '')) not in ('DEVICE', 'ACCESSORY')
      or nullif(btrim(entry.item->>'product_name'), '') is null
      or char_length(btrim(entry.item->>'product_name')) > 200
      or coalesce(entry.item->>'qty', '') !~ '^[1-9][0-9]{0,6}$'
      or (
        nullif(entry.item->>'product_id', '') is not null
        and (entry.item->>'product_id') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      )
  ) then
    raise exception 'SUPPLY_ITEM_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'supply_create',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'supply_create'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  insert into public.supplies (
    order_number,
    from_office,
    to_office,
    tracking_number,
    status,
    imported,
    imported_date,
    comment,
    created_by,
    created_by_id
  )
  values (
    btrim(p_order_number),
    p_from_office,
    p_to_office,
    null,
    'CREATED',
    false,
    null,
    nullif(btrim(coalesce(p_comment, '')), ''),
    btrim(p_actor),
    p_actor_id
  )
  returning * into v_supply;

  insert into public.supply_status_history (
    supply_id,
    status,
    tracking_number,
    changed_by,
    changed_by_id
  )
  values (
    v_supply.id,
    'CREATED',
    null,
    btrim(p_actor),
    p_actor_id
  );

  insert into public.supply_items (
    supply_id,
    product_id,
    product_type,
    product_name,
    qty
  )
  select
    v_supply.id,
    nullif(entry.item->>'product_id', '')::uuid,
    upper(entry.item->>'product_type'),
    btrim(entry.item->>'product_name'),
    (entry.item->>'qty')::integer
  from jsonb_array_elements(p_items) as entry(item);

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'supply', to_jsonb(v_supply)
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_supply_order(p_operation_id uuid, p_actor_id uuid, p_supply_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_supply public.supplies%rowtype;
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or p_supply_id is null then
    raise exception 'SUPPLY_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'supply_delete',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'supply_delete'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select supply.*
  into v_supply
  from public.supplies supply
  where supply.id = p_supply_id
  for update of supply;

  if not found then
    raise exception 'SUPPLY_NOT_FOUND' using errcode = 'P0002';
  end if;

  if lower(v_supply.status) in ('imported', 'failed') then
    raise exception 'SUPPLY_TERMINAL_LOCKED' using errcode = '23514';
  end if;

  delete from public.supplies
  where id = p_supply_id;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'deleted_order_number', v_supply.order_number
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.end_app_session(p_user_id uuid, p_session_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_ended boolean;
begin
  update public.profiles
  set current_session_id = null,
      last_seen_at = statement_timestamp()
  where user_id = p_user_id
    and current_session_id = p_session_id
  returning true into v_ended;

  return coalesce(v_ended, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.fill_device_from_box()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.device_id is null and new.box_id is not null then
    select bin_id
    into new.device_id
    from public.boxes
    where id = new.box_id;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_latest_outbound_movements(p_imeis text[])
 RETURNS TABLE(imei text, created_at timestamp with time zone, shipment_ref text, source text, device text, box_code text, floor text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select distinct on (m.imei)
    m.imei,
    m.created_at,
    m.shipment_ref,
    m.source,
    coalesce(bn.name, ''),
    coalesce(b.box_code, ''),
    coalesce(b.floor, '')
  from public.movements m
  left join public.boxes b on b.id = m.box_id
  left join public.bins bn on bn.id = m.device_id
  where m.type = 'OUT'
    and m.imei = any(p_imeis)
  order by m.imei, m.created_at desc, m.movement_id desc;
$function$;

CREATE OR REPLACE FUNCTION public.get_outbound_box_stock_counts(p_box_ids uuid[])
 RETURNS TABLE(box_id uuid, stock_count bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    requested.box_id,
    count(i.item_id) filter (where upper(i.status) = 'IN')
  from unnest(p_box_ids) as requested(box_id)
  left join public.items i on i.box_id = requested.box_id
  group by requested.box_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_return_history_page(p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_history_key text DEFAULT NULL::text, p_limit integer DEFAULT 51)
 RETURNS TABLE(history_key text, operation_id uuid, created_at timestamp with time zone, actor text, return_ref text, return_type text, return_reason text, qty integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    h.history_key,
    h.operation_id,
    h.created_at,
    h.actor,
    h.return_ref,
    h.return_type,
    h.return_reason,
    h.qty
  from public.return_history_entries h
  where (
    p_cursor_created_at is null
    and p_cursor_history_key is null
  ) or (
    p_cursor_created_at is not null
    and p_cursor_history_key is not null
    and (h.created_at, h.history_key)
      < (p_cursor_created_at, p_cursor_history_key)
  )
  order by h.created_at desc, h.history_key desc
  limit least(greatest(coalesce(p_limit, 51), 1), 51);
$function$;

CREATE OR REPLACE FUNCTION public.get_return_history_page(p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_history_key text DEFAULT NULL::text, p_limit integer DEFAULT 51, p_search text DEFAULT NULL::text, p_month date DEFAULT NULL::date, p_return_status text DEFAULT NULL::text, p_courier text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text)
 RETURNS TABLE(history_key text, operation_id uuid, created_at timestamp with time zone, actor text, return_ref text, return_type text, return_reason text, qty integer, customer text, sur_id text, courier text, country_code text, return_status text, device text, imei text, previous_box text, previous_floor text, target_box text, target_floor text, stock_action text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    r.id::text,
    r.operation_id,
    r.created_at,
    r.actor,
    r.return_ref,
    r.return_type,
    r.return_reason,
    1,
    r.customer,
    r.sur_id,
    r.courier,
    r.country_code,
    r.return_status,
    coalesce(nullif(btrim(r.reported_device), ''), b.name, ''),
    r.imei,
    r.previous_box,
    r.previous_floor,
    r.target_box,
    r.target_floor,
    r.stock_action
  from public.return_records r
  left join public.bins b on b.id = r.device_id
  where (
    (
      p_cursor_created_at is null
      and p_cursor_history_key is null
    ) or (
      p_cursor_created_at is not null
      and p_cursor_history_key is not null
      and (r.created_at, r.id::text)
        < (p_cursor_created_at, p_cursor_history_key)
    )
  )
  and (
    nullif(btrim(coalesce(p_search, '')), '') is null
    or lower(concat_ws(
      ' ',
      r.return_ref,
      r.sur_id,
      r.customer,
      r.imei,
      r.actor,
      r.reported_device,
      b.name
    )) like '%' || lower(btrim(p_search)) || '%'
  )
  and (
    p_month is null
    or (
      r.created_at >= (p_month::timestamp at time zone 'Europe/Brussels')
      and r.created_at < ((p_month + interval '1 month')::timestamp at time zone 'Europe/Brussels')
    )
  )
  and (
    nullif(btrim(coalesce(p_return_status, '')), '') is null
    or r.return_status = lower(btrim(p_return_status))
  )
  and (
    nullif(btrim(coalesce(p_courier, '')), '') is null
    or r.courier = upper(btrim(p_courier))
  )
  and (
    nullif(btrim(coalesce(p_country_code, '')), '') is null
    or r.country_code = upper(btrim(p_country_code))
  )
  order by r.created_at desc, r.id desc
  limit least(greatest(coalesce(p_limit, 51), 1), 51);
$function$;

CREATE OR REPLACE FUNCTION public.get_return_operation_history_page(p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_history_key text DEFAULT NULL::text, p_limit integer DEFAULT 51, p_search text DEFAULT NULL::text, p_month date DEFAULT NULL::date, p_return_status text DEFAULT NULL::text, p_courier text DEFAULT NULL::text, p_country_code text DEFAULT NULL::text)
 RETURNS TABLE(history_key text, operation_id uuid, created_at timestamp with time zone, actor text, return_ref text, return_type text, return_reason text, item_count bigint, customer text, sur_id text, courier text, country_code text, return_status text, device_summary text, device_count bigint, stock_action text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  with resolved_records as (
    select
      r.*,
      coalesce(r.operation_id::text, 'record:' || r.id::text) as operation_key,
      coalesce(nullif(btrim(r.reported_device), ''), b.name, '') as resolved_device
    from public.return_records r
    left join public.bins b on b.id = r.device_id
  ), operations as (
    select
      rr.operation_key,
      max(rr.operation_id::text)::uuid as operation_id,
      max(rr.created_at) as created_at,
      max(rr.actor) as actor,
      max(rr.return_ref) as return_ref,
      max(rr.return_type) as return_type,
      max(rr.return_reason) as return_reason,
      count(*)::bigint as item_count,
      max(rr.customer) as customer,
      max(rr.sur_id) as sur_id,
      max(rr.courier) as courier,
      max(rr.country_code) as country_code,
      max(rr.return_status) as return_status,
      case
        when count(distinct nullif(rr.resolved_device, '')) = 0 then ''
        when count(distinct nullif(rr.resolved_device, '')) = 1
          then max(rr.resolved_device)
        else count(distinct nullif(rr.resolved_device, ''))::text || ' devices'
      end as device_summary,
      count(distinct nullif(rr.resolved_device, ''))::bigint as device_count,
      case
        when bool_and(rr.stock_action = 'added_to_stock') then 'added_to_stock'
        when bool_and(rr.stock_action = 'no_stock_change') then 'no_stock_change'
        else 'mixed'
      end as stock_action
    from resolved_records rr
    group by rr.operation_key
  )
  select
    operation.operation_key,
    operation.operation_id,
    operation.created_at,
    operation.actor,
    operation.return_ref,
    operation.return_type,
    operation.return_reason,
    operation.item_count,
    operation.customer,
    operation.sur_id,
    operation.courier,
    operation.country_code,
    operation.return_status,
    operation.device_summary,
    operation.device_count,
    operation.stock_action
  from operations operation
  where (
    (
      p_cursor_created_at is null
      and p_cursor_history_key is null
    ) or (
      p_cursor_created_at is not null
      and p_cursor_history_key is not null
      and (operation.created_at, operation.operation_key)
        < (p_cursor_created_at, p_cursor_history_key)
    )
  )
  and (
    nullif(btrim(coalesce(p_search, '')), '') is null
    or exists (
      select 1
      from resolved_records matching
      where matching.operation_key = operation.operation_key
        and lower(concat_ws(
          ' ',
          matching.return_ref,
          matching.sur_id,
          matching.customer,
          matching.imei,
          matching.actor,
          matching.resolved_device
        )) like '%' || lower(btrim(p_search)) || '%'
    )
  )
  and (
    p_month is null
    or (
      operation.created_at >=
        (p_month::timestamp at time zone 'Europe/Brussels')
      and operation.created_at <
        ((p_month + interval '1 month')::timestamp at time zone 'Europe/Brussels')
    )
  )
  and (
    nullif(btrim(coalesce(p_return_status, '')), '') is null
    or operation.return_status = lower(btrim(p_return_status))
  )
  and (
    nullif(btrim(coalesce(p_courier, '')), '') is null
    or operation.courier = upper(btrim(p_courier))
  )
  and (
    nullif(btrim(coalesce(p_country_code, '')), '') is null
    or operation.country_code = upper(btrim(p_country_code))
  )
  order by operation.created_at desc, operation.operation_key desc
  limit least(greatest(coalesce(p_limit, 51), 1), 51);
$function$;

CREATE OR REPLACE FUNCTION public.is_admin(uid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
  select private.is_admin(uid);
$function$;

CREATE OR REPLACE FUNCTION public.preview_box_transfer(p_box_codes text[], p_source_bin_id uuid, p_target_floor text)
 RETURNS TABLE(box_id uuid, box_code text, current_floor text, device text, imei_count bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select
    b.id,
    b.box_code,
    b.floor,
    coalesce(bn.name, 'Unknown'),
    count(i.item_id) filter (where upper(i.status) = 'IN')
  from public.boxes b
  left join public.bins bn on bn.id = b.bin_id
  left join public.items i on i.box_id = b.id
  where b.bin_id = p_source_bin_id
    and b.box_code = any(p_box_codes)
  group by b.id, b.box_code, b.floor, bn.name
  order by b.box_code;
$function$;

