 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  -- no-op (QR handled elsewhere)
  return;
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_dispatch_packaging_preference(p_composition_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_latest record;
  v_count integer;
begin
  if coalesce(p_composition_key, '') !~ '^[a-f0-9]{64}$' then
    raise exception 'DISPATCH_COMPOSITION_KEY_INVALID' using errcode = '22023';
  end if;

  -- Latest confirmed order with this composition and 1 to 20 valid packages.
  select
    batch.id as batch_id,
    batch.actor_email,
    batch.confirmed_at,
    order_row.value -> 'items' as composition,
    (
      select jsonb_agg(
        jsonb_build_object(
          'packagingTypeId', package_row.value ->> 'packagingTypeId',
          'quantity', (package_row.value ->> 'quantity')::integer
        )
        order by package_row.ordinality
      )
      from jsonb_array_elements(order_row.value -> 'packages')
        with ordinality as package_row(value, ordinality)
    ) as packages
  into v_latest
  from public.dispatch_batches batch
  cross join lateral jsonb_array_elements(batch.orders) as order_row(value)
  where batch.status = 'CONFIRMED'
    and order_row.value ->> 'compositionKey' = p_composition_key
    and jsonb_typeof(order_row.value -> 'items') = 'array'
    and jsonb_typeof(order_row.value -> 'packages') = 'array'
    and jsonb_array_length(order_row.value -> 'packages') between 1 and 20
    and not exists (
      select 1
      from jsonb_array_elements(order_row.value -> 'packages') as package_row(value)
      where coalesce(package_row.value ->> 'packagingTypeId', '')
          !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        or coalesce(package_row.value ->> 'quantity', '') !~ '^[1-9][0-9]{0,6}$'
    )
  order by batch.confirmed_at desc, batch.id desc
  limit 1;

  if not found then
    delete from public.dispatch_packaging_preferences preference
    where preference.composition_key = p_composition_key;
    return;
  end if;

  select count(*)::integer
  into v_count
  from public.dispatch_batches batch
  cross join lateral jsonb_array_elements(batch.orders) as order_row(value)
  where batch.status = 'CONFIRMED'
    and order_row.value ->> 'compositionKey' = p_composition_key
    and jsonb_typeof(order_row.value -> 'packages') = 'array'
    and jsonb_array_length(order_row.value -> 'packages') between 1 and 20;

  insert into public.dispatch_packaging_preferences (
    composition_key,
    composition,
    packaging_type_id,
    package_quantity,
    packages,
    confirmation_count,
    last_confirmed_batch_id,
    last_actor_email,
    last_confirmed_at,
    created_at,
    updated_at
  ) values (
    p_composition_key,
    coalesce(v_latest.composition, '[]'::jsonb),
    (v_latest.packages -> 0 ->> 'packagingTypeId')::uuid,
    (v_latest.packages -> 0 ->> 'quantity')::integer,
    v_latest.packages,
    greatest(v_count, 1),
    v_latest.batch_id,
    v_latest.actor_email,
    v_latest.confirmed_at,
    clock_timestamp(),
    clock_timestamp()
  )
  on conflict (composition_key) do update
  set composition = excluded.composition,
      packaging_type_id = excluded.packaging_type_id,
      package_quantity = excluded.package_quantity,
      packages = excluded.packages,
      confirmation_count = excluded.confirmation_count,
      last_confirmed_batch_id = excluded.last_confirmed_batch_id,
      last_actor_email = excluded.last_actor_email,
      last_confirmed_at = excluded.last_confirmed_at,
      updated_at = clock_timestamp();
end;
$function$;

CREATE OR REPLACE FUNCTION public.release_return_template_export_batch(p_batch_id uuid, p_actor_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_released integer;
begin
  if p_batch_id is null or p_actor_id is null then
    raise exception 'RETURN_TEMPLATE_EXPORT_IDENTITY_REQUIRED'
      using errcode = '22023';
  end if;

  update public.return_records r
  set template_export_batch_id = null,
      template_exported_at = null,
      template_exported_by = null,
      template_exported_by_email = null
  where r.template_export_batch_id = p_batch_id
    and r.template_exported_by = p_actor_id;

  get diagnostics v_released = row_count;

  delete from public.return_template_export_batches b
  where b.id = p_batch_id
    and b.actor_id = p_actor_id;

  return v_released;
end;
$function$;

CREATE OR REPLACE FUNCTION public.release_workload_lease(p_lease_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_deleted integer;
begin
  if p_lease_id is null then
    return false;
  end if;

  delete from public.workload_leases
  where id = p_lease_id;
  get diagnostics v_deleted = row_count;
  return v_deleted = 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_return_device_name(p_device text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_requested text := nullif(btrim(coalesce(p_device, '')), '');
  v_resolved text;
begin
  if v_requested is null or char_length(v_requested) > 200 then
    return null;
  end if;

  select b.name
  into v_resolved
  from public.bins b
  where lower(btrim(b.name)) = lower(v_requested)
  order by b.active desc, b.name
  limit 1;

  if v_resolved is not null then
    return v_resolved;
  end if;

  return case upper(v_requested)
    when 'LMU2640' then 'LMU2640'
    when 'LMU30G600' then 'LMU30G600'
    when 'FMT100' then 'FMT100'
    when 'FMB020' then 'FMB020'
    when 'FMB003' then 'FMB003'
    when 'FMB920' then 'FMB920'
    when 'FMB130' then 'FMB130'
    when 'GL50B' then 'GL50B'
    when 'FMB640' then 'FMB640'
    when 'FMB641' then 'FMB641'
    when 'FMB204' then 'FMB204'
    when 'BADAI' then 'Badai'
    else null
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_workload_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_buckets integer;
  v_leases integer;
  v_connection_events integer;
begin
  delete from public.workload_budget_buckets
  where window_started_at < clock_timestamp() - interval '1 day';
  get diagnostics v_buckets = row_count;

  delete from public.workload_leases
  where expires_at < clock_timestamp() - interval '1 hour';
  get diagnostics v_leases = row_count;

  delete from public.connection_events
  where created_at < clock_timestamp() - interval '90 days';
  get diagnostics v_connection_events = row_count;

  return jsonb_build_object(
    'budget_buckets_deleted', v_buckets,
    'leases_deleted', v_leases,
    'connection_events_deleted', v_connection_events
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_accessory_stock_count(p_operation_id uuid, p_accessory_bin_id uuid, p_stock integer, p_actor_id uuid, p_actor text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_before integer;
  v_recorded boolean := false;
begin
  if p_operation_id is null
    or p_accessory_bin_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'ACCESSORY_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if p_stock is null
    or p_stock < 0
    or p_stock > 1000000
    or nullif(btrim(coalesce(p_reason, '')), '') is null
    or char_length(p_reason) > 200 then
    raise exception 'ACCESSORY_STOCK_COUNT_INVALID' using errcode = '22023';
  end if;

  select coalesce(bin.current_stock, 0)
  into v_before
  from public.accessory_bins bin
  where bin.id = p_accessory_bin_id
  for update;

  if not found then
    raise exception 'ACCESSORY_BINS_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_before <> p_stock then
    update public.accessory_bins
    set current_stock = p_stock
    where id = p_accessory_bin_id;

    insert into public.accessory_movements (
      accessory_bin_id,
      qty,
      movement_type,
      note,
      actor,
      actor_id,
      source,
      operation_id,
      stock_before,
      stock_after
    )
    values (
      p_accessory_bin_id,
      abs(p_stock - v_before),
      'ADJUSTMENT',
      btrim(p_reason),
      btrim(p_actor),
      p_actor_id,
      'manual',
      p_operation_id,
      v_before,
      p_stock
    );

    v_recorded := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'accessory_bin_id', p_accessory_bin_id,
    'stock_before', v_before,
    'stock_after', p_stock,
    'recorded', v_recorded
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_packaging_inventory(p_operation_id uuid, p_actor_id uuid, p_actor text, p_packaging_type_id uuid, p_code text, p_name text, p_category text, p_length_cm numeric, p_width_cm numeric, p_height_cm numeric, p_on_hand_stock integer, p_minimum_stock integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_packaging public.packaging_types%rowtype;
  v_packaging_id uuid;
  v_stock_before integer := 0;
  v_reserved_before integer := 0;
  v_stock_delta integer;
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'PACKAGING_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_code, '')), '') is null
    or upper(btrim(p_code)) !~ '^[A-Z0-9][A-Z0-9_-]{1,49}$'
    or char_length(btrim(coalesce(p_name, ''))) not between 1 and 120
    or p_category is null
    or p_category not in ('BOX', 'BUBBLE_ENVELOPE', 'PLASTIC_ENVELOPE', 'SLEEVE')
    or (
      p_category = 'SLEEVE'
      and (p_length_cm is not null or p_width_cm is not null or p_height_cm is not null)
    )
    or (
      p_category <> 'SLEEVE'
      and (
        p_length_cm is null or p_length_cm <= 0 or p_length_cm > 1000
        or p_width_cm is null or p_width_cm <= 0 or p_width_cm > 1000
        or p_height_cm is null or p_height_cm <= 0 or p_height_cm > 1000
      )
    )
    or p_on_hand_stock is null or p_on_hand_stock < 0 or p_on_hand_stock > 10000000
    or p_minimum_stock is null or p_minimum_stock < 0 or p_minimum_stock > 10000000 then
    raise exception 'PACKAGING_INVENTORY_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'packaging_inventory_save',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'packaging_inventory_save'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  if p_packaging_type_id is null then
    insert into public.packaging_types (
      code,
      name,
      category,
      length_cm,
      width_cm,
      height_cm,
      on_hand_stock,
      reserved_stock,
      minimum_stock,
      active,
      created_by_id,
      created_by_email,
      updated_by_id,
      updated_by_email,
      updated_at
    )
    values (
      upper(btrim(p_code)),
      btrim(p_name),
      p_category,
      p_length_cm,
      p_width_cm,
      p_height_cm,
      p_on_hand_stock,
      0,
      p_minimum_stock,
      true,
      p_actor_id,
      btrim(p_actor),
      p_actor_id,
      btrim(p_actor),
      v_now
    )
    returning * into v_packaging;

    v_packaging_id := v_packaging.id;
  else
    select packaging.*
    into v_packaging
    from public.packaging_types packaging
    where packaging.id = p_packaging_type_id
    for update of packaging;

    if not found then
      raise exception 'PACKAGING_NOT_FOUND' using errcode = 'P0002';
    end if;

    if p_on_hand_stock < v_packaging.reserved_stock then
      raise exception 'PACKAGING_STOCK_BELOW_RESERVED:%:%:%',
        v_packaging.name,
        p_on_hand_stock,
        v_packaging.reserved_stock
        using errcode = '23514';
    end if;

    v_stock_before := v_packaging.on_hand_stock;
    v_reserved_before := v_packaging.reserved_stock;
    v_packaging_id := v_packaging.id;

    update public.packaging_types packaging
    set code = upper(btrim(p_code)),
        name = btrim(p_name),
        category = p_category,
        length_cm = p_length_cm,
        width_cm = p_width_cm,
        height_cm = p_height_cm,
        on_hand_stock = p_on_hand_stock,
        minimum_stock = p_minimum_stock,
        updated_at = v_now,
        updated_by_id = p_actor_id,
        updated_by_email = btrim(p_actor)
    where packaging.id = v_packaging.id
    returning * into v_packaging;
  end if;

  v_stock_delta := p_on_hand_stock - v_stock_before;
  if v_stock_delta <> 0 then
    insert into public.packaging_stock_movements (
      operation_id,
      packaging_type_id,
      movement_type,
      on_hand_delta,
      reserved_delta,
      on_hand_before,
      on_hand_after,
      reserved_before,
      reserved_after,
      reason,
      actor_id,
      actor_email,
      created_at
    )
    values (
      p_operation_id,
      v_packaging_id,
      'COUNT_ADJUSTMENT',
      v_stock_delta,
      0,
      v_stock_before,
      p_on_hand_stock,
      v_reserved_before,
      v_reserved_before,
      case
        when p_packaging_type_id is null
          then 'Initial stock set in Packaging Inventory'
        else 'Stock count updated in Packaging Inventory'
      end,
      p_actor_id,
      btrim(p_actor),
      v_now
    );
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'row', jsonb_build_object(
      'id', v_packaging.id,
      'code', v_packaging.code,
      'name', v_packaging.name,
      'on_hand_stock', v_packaging.on_hand_stock,
      'reserved_stock', v_packaging.reserved_stock,
      'available_stock', v_packaging.on_hand_stock - v_packaging.reserved_stock,
      'minimum_stock', v_packaging.minimum_stock
    )
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_user_access(p_user_id uuid, p_role text, p_permissions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_current_role text;
  v_admin_count bigint;
  v_permissions jsonb;
begin
  if p_role not in ('admin', 'operator', 'viewer') then
    raise exception 'invalid application role'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('stockpro-user-access', 0)
  );

  select role into v_current_role
  from public.user_roles
  where user_id = p_user_id
  for update;

  if v_current_role = 'admin' and p_role <> 'admin' then
    select count(*) into v_admin_count
    from public.user_roles
    where role = 'admin';

    if v_admin_count <= 1 then
      raise exception 'The last administrator cannot be removed'
        using errcode = '23514';
    end if;
  end if;

  v_permissions := jsonb_build_object(
    'can_dashboard', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_dashboard')::boolean, false) end,
    'can_inventory_export', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_inventory_export')::boolean, false) end,
    'can_inbound', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_inbound')::boolean, false) end,
    'can_outbound', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_outbound')::boolean, false) end,
    'can_returns', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_returns')::boolean, false) end,
    'can_transfer', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_transfer')::boolean, false) end,
    'can_labels', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_labels')::boolean, false) end,
    'can_bins', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_bins')::boolean, false) end,
    'can_accessories', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_accessories')::boolean, false) end,
    'can_supply', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_supply')::boolean, false) end,
    'can_nrd', case when p_role = 'admin' then true else coalesce((p_permissions ->> 'can_nrd')::boolean, false) end,
    'can_admin', p_role = 'admin'
  );

  insert into public.user_roles (user_id, role)
  values (p_user_id, p_role)
  on conflict (user_id) do update
  set role = excluded.role;

  insert into public.user_permissions (
    user_id,
    can_dashboard,
    can_inventory_export,
    can_inbound,
    can_outbound,
    can_returns,
    can_transfer,
    can_labels,
    can_bins,
    can_accessories,
    can_supply,
    can_nrd,
    can_admin
  ) values (
    p_user_id,
    (v_permissions ->> 'can_dashboard')::boolean,
    (v_permissions ->> 'can_inventory_export')::boolean,
    (v_permissions ->> 'can_inbound')::boolean,
    (v_permissions ->> 'can_outbound')::boolean,
    (v_permissions ->> 'can_returns')::boolean,
    (v_permissions ->> 'can_transfer')::boolean,
    (v_permissions ->> 'can_labels')::boolean,
    (v_permissions ->> 'can_bins')::boolean,
    (v_permissions ->> 'can_accessories')::boolean,
    (v_permissions ->> 'can_supply')::boolean,
    (v_permissions ->> 'can_nrd')::boolean,
    (v_permissions ->> 'can_admin')::boolean
  )
  on conflict (user_id) do update set
    can_dashboard = excluded.can_dashboard,
    can_inventory_export = excluded.can_inventory_export,
    can_inbound = excluded.can_inbound,
    can_outbound = excluded.can_outbound,
    can_returns = excluded.can_returns,
    can_transfer = excluded.can_transfer,
    can_labels = excluded.can_labels,
    can_bins = excluded.can_bins,
    can_accessories = excluded.can_accessories,
    can_supply = excluded.can_supply,
    can_nrd = excluded.can_nrd,
    can_admin = excluded.can_admin;

  return v_permissions;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.start_dispatch_plan(p_plan_date date, p_planner_id uuid, p_planner_email text, p_source_sha256 text, p_source_filename text, p_orders jsonb, p_labels jsonb, p_replace boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_open public.dispatch_plans%rowtype;
  v_same public.dispatch_plans%rowtype;
  v_assignments integer;
  v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtext('stockpro.dispatch_plan'));

  -- An open plan from an earlier day no longer locks anything.
  update public.dispatch_plans
     set status = 'RELEASED',
         closed_at = now(),
         closed_by_email = 'end of day'
   where status = 'OPEN'
     and plan_date < p_plan_date;

  select * into v_open
    from public.dispatch_plans
   where status = 'OPEN'
     and plan_date = p_plan_date
   for update;

  if found then
    if v_open.planner_id is distinct from p_planner_id then
      return jsonb_build_object(
        'ok', false,
        'code', 'LOCKED',
        'planner_email', v_open.planner_email,
        'started_at', v_open.started_at
      );
    end if;

    if v_open.source_sha256 = p_source_sha256 then
      return jsonb_build_object(
        'ok', true, 'plan_id', v_open.id, 'status', v_open.status, 'resumed', true
      );
    end if;

    if not coalesce(p_replace, false) then
      select count(*) into v_assignments
        from public.dispatch_plan_assignments
       where plan_id = v_open.id;
      return jsonb_build_object(
        'ok', false,
        'code', 'REPLACE_REQUIRED',
        'source_filename', v_open.source_filename,
        'assignment_count', v_assignments
      );
    end if;

    update public.dispatch_plans
       set status = 'REPLACED',
           closed_at = now(),
           closed_by_email = p_planner_email
     where id = v_open.id;
  else
    select * into v_same
      from public.dispatch_plans
     where plan_date = p_plan_date
       and status in ('CONFIRMED', 'RELEASED')
       and source_sha256 = p_source_sha256
     order by created_at desc
     limit 1;
    -- Today's workbook was already confirmed: show that plan again (its
    -- assignments and labels) without locking the other accounts.
    if found and v_same.status = 'CONFIRMED' then
      return jsonb_build_object(
        'ok', true, 'plan_id', v_same.id, 'status', v_same.status, 'resumed', true
      );
    end if;
    -- A planning ended without deduction reopens for whoever imports the
    -- same workbook again, with its assignments.
    if found then
      update public.dispatch_plans
         set status = 'OPEN',
             planner_id = p_planner_id,
             planner_email = p_planner_email,
             started_at = now(),
             closed_at = null,
             closed_by_email = null
       where id = v_same.id;
      return jsonb_build_object(
        'ok', true, 'plan_id', v_same.id, 'status', 'OPEN', 'resumed', true
      );
    end if;
  end if;

  insert into public.dispatch_plans (
    plan_date, status, planner_id, planner_email,
    source_sha256, source_filename, orders, labels
  )
  values (
    p_plan_date, 'OPEN', p_planner_id, p_planner_email,
    p_source_sha256, p_source_filename, p_orders, p_labels
  )
  returning id into v_id;

  return jsonb_build_object('ok', true, 'plan_id', v_id, 'status', 'OPEN', 'resumed', false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.stockpro_device_id_pattern(p_bin_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  select case
    when upper(regexp_replace(coalesce(p_bin_name, ''), '[^A-Za-z0-9]', '', 'g')) like '%MATRIXIQ%'
      or upper(regexp_replace(coalesce(p_bin_name, ''), '[^A-Za-z0-9]', '', 'g')) like '%MATRIXTAGIQ%'
      then '^[0-9]{12}$'
    else '^[0-9]{15}$'
  end
$function$;

CREATE OR REPLACE FUNCTION public.sync_dispatch_packaging_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_key text;
begin
  for v_key in
    select distinct order_row.value ->> 'compositionKey'
    from jsonb_array_elements(new.orders) as order_row(value)
    where coalesce(order_row.value ->> 'compositionKey', '')
      ~ '^[a-f0-9]{64}$'
  loop
    perform public.refresh_dispatch_packaging_preference(v_key);
  end loop;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_legacy_accessory_from_packaging()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.legacy_accessory_bin_id is null then
    return new;
  end if;

  update public.accessory_bins accessory
  set current_stock = new.on_hand_stock,
      minimum_stock = new.minimum_stock,
      active = false
  where accessory.id = new.legacy_accessory_bin_id
    and (
      accessory.current_stock is distinct from new.on_hand_stock
      or accessory.minimum_stock is distinct from new.minimum_stock
      or accessory.active is distinct from false
    );

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_return_history_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if new.command_type <> 'return' or new.result is null then
    return new;
  end if;

  insert into public.return_history_entries (
    history_key,
    operation_id,
    created_at,
    actor,
    return_ref,
    return_type,
    return_reason,
    qty
  )
  select
    new.operation_id::text,
    new.operation_id,
    max(m.created_at),
    coalesce(
      (array_agg(nullif(m.actor, '') order by m.created_at desc)
        filter (where nullif(m.actor, '') is not null))[1],
      'unknown'
    ),
    coalesce(
      (array_agg(nullif(m.shipment_ref, '') order by m.created_at desc)
        filter (where nullif(m.shipment_ref, '') is not null))[1],
      ''
    ),
    coalesce(
      (array_agg(nullif(m.return_type, '') order by m.created_at desc)
        filter (where nullif(m.return_type, '') is not null))[1],
      ''
    ),
    coalesce(
      (array_agg(nullif(m.return_reason, '') order by m.created_at desc)
        filter (where nullif(m.return_reason, '') is not null))[1],
      ''
    ),
    case
      when count(distinct nullif(m.imei, '')) > 0
        then count(distinct nullif(m.imei, ''))::integer
      else coalesce(sum(coalesce(m.qty, 1)), 0)::integer
    end
  from public.movements m
  where m.type = 'RETURN'
    and m.operation_id = new.operation_id
  having count(*) > 0
  on conflict (history_key) do update
  set created_at = excluded.created_at,
      actor = excluded.actor,
      return_ref = excluded.return_ref,
      return_type = excluded.return_type,
      return_reason = excluded.return_reason,
      qty = excluded.qty;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.take_over_app_session(p_user_id uuid, p_session_id text, p_event_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_event_id uuid;
begin
  if p_session_id is null
     or p_session_id !~ '^[A-Za-z0-9_-]{1,128}$' then
    return false;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('stockpro-app-session:' || p_user_id::text, 0)
  );

  select id
    into v_event_id
  from public.connection_events
  where id = p_event_id
    and user_id = p_user_id
    and successful = true
    and takeover = false
    and auth_session_id = p_session_id
    and created_at >= statement_timestamp() - interval '10 minutes'
  for update;

  if v_event_id is null then
    return false;
  end if;

  update public.profiles
  set current_session_id = p_session_id,
      last_seen_at = statement_timestamp()
  where user_id = p_user_id;

  if not found then
    return false;
  end if;

  update public.connection_events
  set takeover = true
  where id = v_event_id;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_app_session(p_user_id uuid, p_session_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_touched boolean;
begin
  update public.profiles
  set last_seen_at = statement_timestamp()
  where user_id = p_user_id
    and current_session_id = p_session_id
    and last_seen_at >= statement_timestamp() - interval '1 hour'
  returning true into v_touched;

  return coalesce(v_touched, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.transition_supply_order(p_operation_id uuid, p_actor_id uuid, p_actor text, p_supply_id uuid, p_status text, p_tracking_number text, p_failed_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_supply public.supplies%rowtype;
  v_updated public.supplies%rowtype;
  v_history public.supply_status_history%rowtype;
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_now timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if p_operation_id is null
    or p_actor_id is null
    or nullif(btrim(p_actor), '') is null
    or p_supply_id is null then
    raise exception 'SUPPLY_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  if v_status not in ('CREATED', 'SHIPPED', 'RECEIVED', 'IMPORTED', 'FAILED')
    or char_length(coalesce(p_tracking_number, '')) > 500
    or char_length(coalesce(p_failed_reason, '')) > 1000
    or (
      v_status = 'FAILED'
      and nullif(btrim(coalesce(p_failed_reason, '')), '') is null
    ) then
    raise exception 'SUPPLY_TRANSITION_INVALID' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  )
  values (
    p_operation_id,
    'supply_transition',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;

  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'supply_transition'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;

    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;

    return v_existing_result;
  end if;

  select supply.*
  into v_supply
  from public.supplies supply
  where supply.id = p_supply_id
  for update of supply;

  if not found then
    raise exception 'SUPPLY_NOT_FOUND' using errcode = 'P0002';
  end if;

  if lower(v_supply.status) in ('imported', 'failed') then
    raise exception 'SUPPLY_TERMINAL_LOCKED' using errcode = '23514';
  end if;

  if not (
    (v_supply.status = 'CREATED' and v_status in ('CREATED', 'SHIPPED', 'FAILED'))
    or (v_supply.status = 'SHIPPED' and v_status in ('SHIPPED', 'RECEIVED', 'FAILED'))
    or (v_supply.status = 'RECEIVED' and v_status in ('RECEIVED', 'IMPORTED', 'FAILED'))
  ) then
    raise exception 'SUPPLY_STATUS_TRANSITION_INVALID' using errcode = '23514';
  end if;

  update public.supplies
  set status = v_status,
      tracking_number = nullif(btrim(coalesce(p_tracking_number, '')), ''),
      failed_reason = case
        when v_status = 'FAILED'
        then btrim(p_failed_reason)
        else null
      end,
      imported = (v_status = 'IMPORTED'),
      imported_date = case
        when v_status = 'IMPORTED' then v_now
        else null
      end,
      updated_at = v_now
  where id = p_supply_id
  returning * into v_updated;

  insert into public.supply_status_history (
    supply_id,
    status,
    tracking_number,
    failed_reason,
    changed_by,
    changed_by_id
  )
  values (
    p_supply_id,
    v_status,
    nullif(btrim(coalesce(p_tracking_number, '')), ''),
    case
      when v_status = 'FAILED'
      then btrim(p_failed_reason)
      else null
    end,
    btrim(p_actor),
    p_actor_id
  )
  returning * into v_history;

  v_result := jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id,
    'row', to_jsonb(v_updated),
    'historyRow', to_jsonb(v_history)
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_items_refresh_box_qr()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  perform public.refresh_box_qr_payload(coalesce(new.box_id, old.box_id));
  return coalesce(new, old);
end;
$function$;

CREATE OR REPLACE FUNCTION public.undo_dispatch_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_receipt_inserted integer;
  v_existing_command text;
  v_existing_actor uuid;
  v_existing_result jsonb;
  v_batch public.dispatch_batches%rowtype;
  v_usage jsonb;
  v_packaging public.packaging_types%rowtype;
  v_packaging_id uuid;
  v_quantity integer;
  v_after integer;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_operation_id is null
    or p_actor_id is null
    or p_batch_id is null
    or nullif(btrim(coalesce(p_actor, '')), '') is null then
    raise exception 'DISPATCH_IDENTITY_REQUIRED' using errcode = '22023';
  end if;

  insert into public.inventory_command_receipts (
    operation_id,
    command_type,
    actor_id
  ) values (
    p_operation_id,
    'dispatch_undo',
    p_actor_id
  )
  on conflict (operation_id) do nothing;

  get diagnostics v_receipt_inserted = row_count;
  if v_receipt_inserted = 0 then
    select receipt.command_type, receipt.actor_id, receipt.result
    into v_existing_command, v_existing_actor, v_existing_result
    from public.inventory_command_receipts receipt
    where receipt.operation_id = p_operation_id;

    if v_existing_command is distinct from 'dispatch_undo'
      or v_existing_actor is distinct from p_actor_id then
      raise exception 'OPERATION_ID_CONFLICT' using errcode = '23505';
    end if;
    if v_existing_result is null then
      raise exception 'OPERATION_RESULT_UNAVAILABLE' using errcode = '40001';
    end if;
    return v_existing_result;
  end if;

  perform pg_advisory_xact_lock(hashtext('stockpro-dispatch-planning'));

  select batch.*
  into v_batch
  from public.dispatch_batches batch
  where batch.id = p_batch_id
  for update of batch;

  if not found then
    raise exception 'DISPATCH_BATCH_NOT_FOUND' using errcode = 'P0002';
  end if;
  if v_batch.status <> 'CONFIRMED' then
    raise exception 'DISPATCH_BATCH_ALREADY_UNDONE' using errcode = '23514';
  end if;

  for v_usage in select value from jsonb_array_elements(v_batch.package_usage)
  loop
    v_packaging_id := (v_usage ->> 'packagingTypeId')::uuid;
    v_quantity := (v_usage ->> 'quantity')::integer;

    select packaging.*
    into v_packaging
    from public.packaging_types packaging
    where packaging.id = v_packaging_id
    for update of packaging;

    if not found then
      raise exception 'PACKAGING_NOT_FOUND' using errcode = 'P0002';
    end if;

    v_after := v_packaging.on_hand_stock + v_quantity;
    update public.packaging_types packaging
    set on_hand_stock = v_after,
        updated_at = v_now,
        updated_by_id = p_actor_id,
        updated_by_email = btrim(p_actor)
    where packaging.id = v_packaging.id;

    insert into public.packaging_stock_movements (
      operation_id,
      packaging_type_id,
      movement_type,
      on_hand_delta,
      reserved_delta,
      on_hand_before,
      on_hand_after,
      reserved_before,
      reserved_after,
      reason,
      actor_id,
      actor_email,
      created_at
    ) values (
      gen_random_uuid(),
      v_packaging.id,
      'UNDO_CONSUME',
      v_quantity,
      0,
      v_packaging.on_hand_stock,
      v_after,
      v_packaging.reserved_stock,
      v_packaging.reserved_stock,
      'Undo daily dispatch ' || v_batch.source_filename,
      p_actor_id,
      btrim(p_actor),
      v_now
    );
  end loop;

  update public.dispatch_batches batch
  set status = 'UNDONE',
      undone_at = v_now,
      undone_by_id = p_actor_id,
      undone_by_email = btrim(p_actor)
  where batch.id = v_batch.id;

  v_result := jsonb_build_object(
    'ok', true,
    'batch_id', v_batch.id,
    'operation_id', p_operation_id,
    'restored_packages', v_batch.total_packages,
    'status', 'UNDONE'
  );

  update public.inventory_command_receipts
  set result = v_result
  where operation_id = p_operation_id;

  return v_result;
end;
$function$;


-- ======================================================================
-- Views
-- ======================================================================

CREATE OR REPLACE VIEW public.dashboard_activity WITH (security_invoker=true) AS
 SELECT m.type,
    b.name AS device,
    count(*)::integer AS qty,
    min(m.created_at) AS created_at,
    NULL::text AS box_code,
    NULL::text AS from_floor,
    NULL::text AS to_floor
   FROM public.movements m
     LEFT JOIN public.bins b ON b.id = m.device_id
  WHERE m.type = ANY (ARRAY['IN'::text, 'OUT'::text, 'RETURN'::text])
  GROUP BY m.operation_id, m.type, b.name
UNION ALL
 SELECT m.type,
    b.name AS device,
    count(*)::integer AS qty,
    min(m.created_at) AS created_at,
    bx.box_code,
    m.from_floor,
    m.to_floor
   FROM public.movements m
     LEFT JOIN public.boxes bx ON bx.id = m.box_id
     LEFT JOIN public.bins b ON b.id = m.device_id
  WHERE m.type = 'TRANSFER'::text
  GROUP BY m.operation_id, m.type, b.name, bx.box_code, m.from_floor, m.to_floor;

CREATE OR REPLACE VIEW public.dashboard_bins_view WITH (security_invoker=true) AS
 SELECT bins.id AS device_id,
    bins.name AS device,
    COALESCE(bins.min_stock, 0) AS min_stock,
    count(DISTINCT items.box_id) FILTER (WHERE items.status = 'IN'::text) AS boxes_count,
    count(items.item_id) FILTER (WHERE items.status = 'IN'::text) AS imei_count,
        CASE
            WHEN count(items.item_id) FILTER (WHERE items.status = 'IN'::text) = 0 THEN 'empty'::text
            WHEN count(items.item_id) FILTER (WHERE items.status = 'IN'::text) <= COALESCE(bins.min_stock, 0) THEN 'low'::text
            ELSE 'ok'::text
        END AS stock_status
   FROM public.bins
     LEFT JOIN public.boxes ON boxes.bin_id = bins.id
     LEFT JOIN public.items ON items.box_id = boxes.id
  GROUP BY bins.id, bins.name, bins.min_stock
 HAVING count(items.item_id) FILTER (WHERE items.status = 'IN'::text) > 0
  ORDER BY bins.name;

CREATE OR REPLACE VIEW public.dashboard_device_flow WITH (security_invoker=true) AS
 WITH current_stock AS (
         SELECT b_1.id AS device_id,
            count(i.item_id)::integer AS total_in
           FROM public.bins b_1
             LEFT JOIN public.boxes bx ON bx.bin_id = b_1.id
             LEFT JOIN public.items i ON i.box_id = bx.id AND i.status = 'IN'::text
          GROUP BY b_1.id
        ), monthly_out AS (
         SELECT m.device_id,
            COALESCE(sum(m.qty), 0::bigint)::integer AS total_out
           FROM public.movements m
          WHERE m.type = 'OUT'::text AND m.created_at >= date_trunc('month'::text, now())
          GROUP BY m.device_id
        )
 SELECT b.name AS device,
    COALESCE(cs.total_in, 0) AS total_in,
    COALESCE(mo.total_out, 0) AS total_out
   FROM public.bins b
     LEFT JOIN current_stock cs ON cs.device_id = b.id
     LEFT JOIN monthly_out mo ON mo.device_id = b.id
  WHERE COALESCE(cs.total_in, 0) > 0 OR COALESCE(mo.total_out, 0) > 0
  ORDER BY b.name;

CREATE OR REPLACE VIEW public.dashboard_drilldown_view WITH (security_invoker=true) AS
 SELECT bins.id AS device_id,
    bins.name AS device,
    boxes.id AS box_id,
    boxes.box_code,
    COALESCE(boxes.floor, '—'::text) AS floor,
    count(*) FILTER (WHERE items.status = 'IN'::text) AS remaining,
    count(*) AS total_ever,
        CASE
            WHEN count(*) = 0 THEN 0::numeric
            ELSE round(count(*) FILTER (WHERE items.status = 'IN'::text)::numeric / count(*)::numeric * 100::numeric)
        END AS percent
   FROM public.boxes
     JOIN public.bins ON bins.id = boxes.bin_id
     LEFT JOIN public.items ON items.box_id = boxes.id
  GROUP BY bins.id, bins.name, boxes.id, boxes.box_code, boxes.floor
 HAVING count(*) FILTER (WHERE items.status = 'IN'::text) > 0
  ORDER BY bins.name, boxes.box_code;

CREATE OR REPLACE VIEW public.dashboard_floors_view WITH (security_invoker=true) AS
 SELECT COALESCE(boxes.floor, '—'::text) AS floor,
    bins.id AS device_id,
    bins.name AS device,
    count(DISTINCT items.box_id) FILTER (WHERE items.status = 'IN'::text) AS boxes_count,
    count(items.item_id) FILTER (WHERE items.status = 'IN'::text) AS imei_count
   FROM public.boxes
     JOIN public.bins ON bins.id = boxes.bin_id
     LEFT JOIN public.items ON items.box_id = boxes.id
  GROUP BY boxes.floor, bins.id, bins.name
 HAVING count(items.item_id) FILTER (WHERE items.status = 'IN'::text) > 0
  ORDER BY (COALESCE(boxes.floor, '—'::text)), bins.name;

CREATE OR REPLACE VIEW public.dashboard_sales_month WITH (security_invoker=true) AS
 SELECT b.name AS device,
    sum(m.qty)::integer AS total_out
   FROM public.movements m
     JOIN public.bins b ON b.id = m.device_id
  WHERE m.type = 'OUT'::text AND date_trunc('month'::text, m.created_at) = date_trunc('month'::text, now())
  GROUP BY b.name
  ORDER BY (sum(m.qty)::integer) DESC;

CREATE OR REPLACE VIEW public.inbound_history_view WITH (security_invoker=true) AS
 SELECT b.batch_id,
    b.created_at,
    b.actor,
    b.vendor,
    b.source,
    b.shipment_ref,
    count(DISTINCT bx.id) AS qty_boxes,
    count(i.item_id) AS qty_imeis
   FROM public.inbound_batches b
     LEFT JOIN public.items i ON i.import_id = b.batch_id
     LEFT JOIN public.boxes bx ON bx.id = i.box_id
  GROUP BY b.batch_id, b.created_at, b.actor, b.vendor, b.source, b.shipment_ref
  ORDER BY b.created_at DESC;

CREATE OR REPLACE VIEW public.stock_export_view WITH (security_invoker=true) AS
 SELECT i.item_id,
    i.imei,
    b.id AS device_id,
    b.name AS device,
    bx.id AS box_id,
    bx.box_code,
    bx.floor
   FROM public.items i
     LEFT JOIN public.boxes bx ON bx.id = i.box_id
     LEFT JOIN public.bins b ON b.id = bx.bin_id
  WHERE i.status = 'IN'::text;


-- ======================================================================
-- Foreign keys
-- ======================================================================

ALTER TABLE ONLY public.accessory_movements ADD CONSTRAINT accessory_movements_accessory_bin_id_fkey FOREIGN KEY (accessory_bin_id) REFERENCES public.accessory_bins(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.audit_events ADD CONSTRAINT audit_events_created_by_fkey FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE RESTRICT;

ALTER TABLE ONLY public.boxes ADD CONSTRAINT boxes_bin_id_fkey FOREIGN KEY (bin_id) REFERENCES public.bins(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.connection_events ADD CONSTRAINT connection_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.device_accessory_templates ADD CONSTRAINT device_accessory_templates_accessory_bin_id_fkey FOREIGN KEY (accessory_bin_id) REFERENCES public.accessory_bins(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.device_accessory_templates ADD CONSTRAINT device_accessory_templates_device_id_fkey FOREIGN KEY (device_id) REFERENCES public.bins(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.device_inbound_accessories ADD CONSTRAINT device_inbound_accessories_accessory_bin_id_fkey FOREIGN KEY (accessory_bin_id) REFERENCES public.accessory_bins(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.device_inbound_accessories ADD CONSTRAINT device_inbound_accessories_device_id_fkey FOREIGN KEY (device_id) REFERENCES public.bins(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.dispatch_batches ADD CONSTRAINT dispatch_batches_actor_id_fkey FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.dispatch_batches ADD CONSTRAINT dispatch_batches_undone_by_id_fkey FOREIGN KEY (undone_by_id) REFERENCES auth.users(id) ON DELETE SET NULL;

ALTER TABLE ONLY public.dispatch_packaging_preferences ADD CONSTRAINT dispatch_packaging_preferences_last_confirmed_batch_id_fkey FOREIGN KEY (last_confirmed_batch_id) REFERENCES public.dispatch_batches(id) ON DELETE CASCADE;

ALTER TABLE ONLY public.dispatch_packaging_preferences ADD CONSTRAINT dispatch_packaging_preferences_packaging_type_id_fkey FOREIGN KEY (packaging_type_id) REFERENCES public.packaging_types(id) ON DELETE RESTRICT;

ALTER TABLE ONLY public.dispatch_plan_assignments ADD CONSTRAINT dispatch_plan_assignments_assignee_id_fkey FOREIGN KEY (assignee_id) REFERENCES auth.users(id) ON DELETE CASCADE;

