-- ======================================================================
-- Triggers
-- ======================================================================

CREATE TRIGGER trg_device_thresholds_updated_at BEFORE UPDATE ON public.device_thresholds FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER trg_devices_updated_at BEFORE UPDATE ON public.devices FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER dispatch_packaging_preferences_sync AFTER INSERT OR UPDATE OF status ON public.dispatch_batches FOR EACH ROW EXECUTE FUNCTION public.sync_dispatch_packaging_preferences();

CREATE TRIGGER inventory_receipt_return_history AFTER UPDATE OF result ON public.inventory_command_receipts FOR EACH ROW WHEN (new.command_type = 'return'::text AND new.result IS NOT NULL) EXECUTE FUNCTION public.sync_return_history_receipt();

CREATE TRIGGER items_refresh_box_qr AFTER INSERT OR DELETE OR UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.trg_items_refresh_box_qr();

CREATE TRIGGER trg_items_updated_at BEFORE UPDATE ON public.items FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER check_stock_before_out BEFORE INSERT ON public.movements FOR EACH ROW EXECUTE FUNCTION public.check_stock_before_out();

CREATE TRIGGER trg_fill_device_from_box BEFORE INSERT ON public.movements FOR EACH ROW EXECUTE FUNCTION public.fill_device_from_box();

CREATE TRIGGER packaging_types_sync_legacy_stock AFTER UPDATE OF on_hand_stock, minimum_stock ON public.packaging_types FOR EACH ROW EXECUTE FUNCTION public.sync_legacy_accessory_from_packaging();

CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();


