-- ======================================================================
-- Policies
-- ======================================================================

CREATE POLICY alert_log_admin_read ON public.alert_log AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.is_admin(( SELECT auth.uid() AS uid)));

CREATE POLICY alert_subscribers_admin_all ON public.alert_subscribers AS PERMISSIVE FOR ALL TO authenticated
    USING (private.is_admin(( SELECT auth.uid() AS uid)))
    WITH CHECK (private.is_admin(( SELECT auth.uid() AS uid)));

CREATE POLICY audit_events_admin_read ON public.audit_events AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.is_admin(( SELECT auth.uid() AS uid)));

CREATE POLICY bins_authenticated_read ON public.bins AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.has_app_role(( SELECT auth.uid() AS uid)));

CREATE POLICY bins_permission_write ON public.bins AS PERMISSIVE FOR ALL TO authenticated
    USING (private.has_permission(( SELECT auth.uid() AS uid), 'can_bins'::text))
    WITH CHECK (private.has_permission(( SELECT auth.uid() AS uid), 'can_bins'::text));

CREATE POLICY boxes_authenticated_read ON public.boxes AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.has_app_role(( SELECT auth.uid() AS uid)));

CREATE POLICY boxes_permission_update ON public.boxes AS PERMISSIVE FOR UPDATE TO authenticated
    USING ((private.has_permission(( SELECT auth.uid() AS uid), 'can_transfer'::text) OR private.has_permission(( SELECT auth.uid() AS uid), 'can_bins'::text)))
    WITH CHECK ((private.has_permission(( SELECT auth.uid() AS uid), 'can_transfer'::text) OR private.has_permission(( SELECT auth.uid() AS uid), 'can_bins'::text)));

CREATE POLICY thresholds_authenticated_read ON public.device_thresholds AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.has_app_role(( SELECT auth.uid() AS uid)));

CREATE POLICY devices_authenticated_read ON public.devices AS PERMISSIVE FOR SELECT TO authenticated
    USING (private.has_app_role(( SELECT auth.uid() AS uid)));

CREATE POLICY profiles_select_active_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated
    USING (((( SELECT auth.uid() AS uid) = user_id) AND private.has_active_app_session(( SELECT auth.uid() AS uid))));

CREATE POLICY user_permissions_select_active_own ON public.user_permissions AS PERMISSIVE FOR SELECT TO authenticated
    USING (((( SELECT auth.uid() AS uid) = user_id) AND private.has_active_app_session(( SELECT auth.uid() AS uid))));

CREATE POLICY user_roles_select_active_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated
    USING (((( SELECT auth.uid() AS uid) = user_id) AND private.has_active_app_session(( SELECT auth.uid() AS uid))));


