-- ======================================================================
-- Default privileges
-- ======================================================================

ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT SELECT, UPDATE, USAGE ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLES TO service_role;

-- ======================================================================
-- Comments
-- ======================================================================

COMMENT ON SCHEMA public IS 'standard public schema';

COMMENT ON COLUMN public.accessory_bins.kinesis_names IS 'Kinesis Hardware Type labels that refer to this accessory; the first one names it in dispatch packing lists.';

COMMENT ON COLUMN public.bins.kinesis_names IS 'Kinesis Hardware Type labels that refer to this device model.';

COMMENT ON FUNCTION public.check_existing_imeis(requested_imeis text[]) IS 'Bounded exact-match IMEI lookup for users with can_inbound.';

COMMENT ON FUNCTION public.claim_return_template_export_batch(p_batch_id uuid, p_actor_id uuid, p_actor text, p_limit integer) IS 'Atomically claims previously unexported customer-return rows for one template download.';

COMMENT ON FUNCTION public.claim_return_template_export_batch_v2(p_batch_id uuid, p_actor_id uuid, p_actor text, p_limit integer) IS 'Atomically claims pending return rows and includes the official reason required by the Control workbook.';

COMMENT ON FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text) IS 'Atomically returns canonical OUT items to boxes and records RETURN movements.';

COMMENT ON FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text) IS 'Records complete customer-return metadata and changes stock only for Available returns.';

COMMENT ON FUNCTION public.confirm_return_batch(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text) IS 'Uses canonical device data for Available returns and a validated reported device for non-stock returns.';

COMMENT ON FUNCTION public.confirm_return_batch_v2(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_target_box text, p_target_floor text, p_return_ref text, p_return_type text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text, p_unknown_imeis text[]) IS 'Confirms canonical Available returns and audit-only non-stock returns, including IMEIs absent from inventory.';

COMMENT ON FUNCTION public.confirm_return_batch_v3(p_operation_id uuid, p_actor_id uuid, p_actor text, p_item_ids uuid[], p_unknown_imeis text[], p_target_box text, p_target_floor text, p_return_ref text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text, p_reported_device text) IS 'Confirms customer returns with the Control reason catalogue and no operator-facing return type.';

COMMENT ON FUNCTION public.confirm_return_batch_v4(p_operation_id uuid, p_actor_id uuid, p_actor text, p_items jsonb, p_target_box text, p_target_floor text, p_return_ref text, p_return_reason text, p_return_status text, p_courier text, p_country_code text, p_customer text, p_sur_id text) IS 'Confirms one customer return operation containing multiple device models with a validated device per non-stock IMEI.';

COMMENT ON TABLE public.connection_events IS 'Admin-only StockPro authentication log. Application retention: 90 days.';

COMMENT ON COLUMN public.device_accessory_templates.per_order IS 'true: quantity is removed once per order that contains this device model; per_devices is then ignored.';

COMMENT ON TABLE public.dispatch_packaging_preferences IS 'Latest confirmed real packaging choice for each normalized dispatch composition.';

COMMENT ON FUNCTION public.get_return_history_page(p_cursor_created_at timestamp with time zone, p_cursor_history_key text, p_limit integer, p_search text, p_month date, p_return_status text, p_courier text, p_country_code text) IS 'Bounded, filterable, per-IMEI customer return history.';

COMMENT ON FUNCTION public.get_return_operation_history_page(p_cursor_created_at timestamp with time zone, p_cursor_history_key text, p_limit integer, p_search text, p_month date, p_return_status text, p_courier text, p_country_code text) IS 'Returns one bounded, filterable history row per return operation.';

COMMENT ON COLUMN public.movements.device_id IS 'Legacy column name: stores public.bins.id for inventory movements.';

COMMENT ON COLUMN public.packaging_types.legacy_accessory_bin_id IS 'Read-only compatibility mirror for historical Packages accessory rows. Packaging Inventory is the canonical stock source.';

COMMENT ON FUNCTION public.refresh_dispatch_packaging_preference(p_composition_key text) IS 'Rebuilds one adaptive packaging preference from confirmed dispatch history.';

COMMENT ON FUNCTION public.release_return_template_export_batch(p_batch_id uuid, p_actor_id uuid) IS 'Releases a claimed template export only when workbook generation fails before delivery.';

COMMENT ON TABLE public.return_history_entries IS 'Operation-level RETURN history used for bounded cursor pagination.';

COMMENT ON TABLE public.return_records IS 'One immutable audit record per customer-returned IMEI, including non-stock returns.';

COMMENT ON COLUMN public.return_records.item_id IS 'Canonical item when known; null only for audit-only non-stock returns whose IMEI is absent from inventory.';

COMMENT ON COLUMN public.return_records.movement_id IS 'Inventory movement when canonical stock is involved; null for unknown audit-only non-stock returns.';

COMMENT ON COLUMN public.return_records.reported_device IS 'Canonical device for Available returns, or the operator-selected device for non-stock returns.';

COMMENT ON TABLE public.security_alert_recipients IS 'Administrators designated as IT contacts: only they see the security update alert (everyone with the admin role sees it while this list is empty).';

COMMENT ON COLUMN public.user_permissions.can_inventory_export IS 'Allows global exports containing raw IMEIs and warehouse locations.';

COMMENT ON TABLE public.workload_budget_buckets IS 'HMAC-keyed fixed-window counters for StockPro shared workload admission.';

COMMENT ON TABLE public.workload_leases IS 'Expiring cross-instance leases for bounded StockPro concurrency.';
